		id = 930061011
	},
	[930061012] = {
		speaker = "禄良",
		prefab_name = "",
		content = "依他的性子，多半是听说馆主每天都要来道馆就逃了。他倒是逃了，但道馆已经建好逃不掉了。",
		id = 930061012
	},
	[930061013] = {
