		id = 424101047
	},
	[424101048] = {
		speaker = "",
		prefab_name = "",
		content = "回忆的碎片如同冰冷的潮水涌上心头，老妇人那刻骨的恐惧、避之不及的嫌恶、口口声声的“诅咒”……一切都有了令人心寒的注解。",
		id = 424101048
	},
	[424101049] = {
