	},
	[1104911200] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "嗯，谢谢你，问号。",
		id = 1104911200
	},
	[1104911201] = {
		speaker = "",
		prefab_name = "",
		content = "跟着千堂的步伐，我们一行人进入了祠堂内。堂前大道已分好了坐席，两位传统服饰打扮的人在殿前驻立，殿后的巨樱随着风簌簌飘落许多花瓣。",
		id = 1104911201
	},
	[1104911202] = {
		speaker = "鸦越千堂",
		prefab_name = "10053ui_story",
		content = "之后的祈福就在这里办，这两位司仪会在堂前为你们主持仪式。先入席吧，她们会指引接下来该怎么做。",
		id = 1104911202
	},
	[1104911203] = {
		speaker = "",
		prefab_name = "",
		content = "千堂回到了后面的亲朋席中，两位宫司将我们引到了堂前的主席位坐下，随后从殿内取来了一把金色的小壶和三只不同大小的碗碟，放在我们面前。",
		id = 1104911203
	},
	[1104911204] = {
		speaker = "我",
		prefab_name = "",
		content = "这是？",
		id = 1104911204
	},
	[1104911205] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "问号，读书不仔细呢。",
		id = 1104911205
	},
	[1104911206] = {
		speaker = "我",
		prefab_name = "",
		content = "咳，昨晚不小心睡着了，后面的没怎么看到……",
		id = 1104911206
	},
	[1104911207] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "嗯，我知道，因为问号今早看起来睡得很香。",
		id = 1104911207
	},
	[1104911208] = {
		speaker = "",
		prefab_name = "",
		content = "听到这话，我的脸顿时温度高了不少，千羽好像很满意眼前画面的样子，嘴边绽放出浅浅的微笑。",
		id = 1104911208
	},
	[1104911209] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "这是三献之仪，宫司们会将笹波的山泉倒入碗中，然后由我们交替着喝下。",
		id = 1104911209
	},
	[1104911210] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "第一杯代表对过往的感谢，由你先。",
		id = 1104911210
	},
	[1104911211] = {
		speaker = "",
		prefab_name = "",
		content = "我接过由宫司递来的清泉，将红色的碗碟对上了唇边，准备一饮而尽。旁边一直注视着我的千羽用手轻轻贴在了我的手上，示意我停下。",
		id = 1104911211
	},
	[1104911212] = {
		speaker = "我",
		prefab_name = "",
		content = "是我做的有哪里不对吗？",
