	},
	[1104911213] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "要举杯三次才能喝完，我来教你吧。",
		id = 1104911213
	},
	[1104911214] = {
		speaker = "",
		prefab_name = "",
		content = "千羽接过了我手上的碗碟，将它举起两次，随后在第三次时递到自己嘴边，然后看向了我。我学着千羽的姿势，将杯中的清泉饮尽。",
		id = 1104911214
	},
	[1104911215] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "嗯，很完美。",
		id = 1104911215
