	},
	[1104911219] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "生死婚寿，每一件都是生命中的大事，自然每个步骤都会承载着希冀。",
		id = 1104911219
	},
	[1104911220] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "不过我更在乎这些意义背后的价值。",
		id = 1104911220
	},
	[1104911221] = {
		speaker = "",
		prefab_name = "",
		content = "千羽拿起了我刚刚喝过的碗碟，待宫司斟满山泉后，分三次饮下。喝完后，她静静地望着手中的空碗，过了许久才放下。",
		id = 1104911221
	},
	[1104911222] = {
		speaker = "我",
		prefab_name = "",
		content = "看起来，这份过往对你来说很重要。",
