	},
	[1104911228] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "哦？问号要怎么见她？",
		id = 1104911228
	},
	[1104911229] = {
		speaker = "我",
		prefab_name = "",
		content = "去你带我去过的地方吧。",
		id = 1104911229
	},
	[1104912001] = {
		speaker = "",
		prefab_name = "",
		content = "趁着彩排休息的间隙，我和千羽轻车熟路地穿过林间的小路到达了后山的墓地。这里还是如往常那般安静，只有风穿过树叶的沙沙声。",
		id = 1104912001
	},
	[1104912002] = {
		speaker = "",
		prefab_name = "",
		content = "上次站在墓碑前是千羽向母亲介绍我的存在，而这次站在这里，则是我要向母亲承诺与千羽的未来。",
		id = 1104912002
	},
	[1104912003] = {
		speaker = "我",
		prefab_name = "",
		content = "自上次一别以来已经过去很久了，很抱歉没能常来看您。这次来是想告诉您，我和千羽要办婚礼了。",
		id = 1104912003
	},
	[1104912004] = {
		speaker = "我",
		prefab_name = "",
		content = "既然已经成为了千羽未来最重要的人，我一定会让她幸福。",
		id = 1104912004
	},
	[1104912005] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "没想到问号对那时的话还记得这么清楚。",
		id = 1104912005
	},
	[1104912006] = {
		speaker = "我",
		prefab_name = "",
		content = "毕竟你当时将我介绍给了母亲，这么重要的时刻我不可能会忘。",
		id = 1104912006
	},
	[1104912007] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "能在这里听到你说这些，母亲一定会开心的。",
		id = 1104912007
	},
	[1104912008] = {
		speaker = "",
		prefab_name = "",
		content = "阳光透过树叶的间隙洒在墓碑上，千羽笑着挽起了我的手，头轻轻靠在我的肩上，温柔地注视着前方。",
		id = 1104912008
	},
	[1104912009] = {
		speaker = "我",
		prefab_name = "",
		content = "这里对你的母亲来说有什么特殊的意义吗？",
		id = 1104912009
	},
	[1104912010] = {
		speaker = "伊邪那美",
		prefab_name = "1049ui_story",
		content = "曾经母亲的婚礼就是在这里举办的。",
		id = 1104912010
	},
	[1104912011] = {
		speaker = "我",
		prefab_name = "",
		content = "你是说，在这些墓碑前？",
		id = 1104912011
