	},
	[323011046] = {
		speaker = "定远",
		prefab_name = "10163ui_story",
		content = "你是传令官，是将军的旗，这身皮是整支部队的脸面，别糟蹋了。",
		id = 323011046
	},
	[323011047] = {
		speaker = "",
		prefab_name = "",
		content = "定远松开当归，重新替他整理衣甲。当归没再抗拒，无所事事地左顾右盼，看到一位年纪与自己相仿的姑娘跟在老包儿后面，提着蒸笼从后厨走出来。",
		id = 323011047
	},
	[323011048] = {
		speaker = "",
		prefab_name = "",
		content = "当归冲那姑娘笑了笑。姑娘忍不住也笑了，但又有些不好意思，拿蒸笼遮住自己的脸，然后帮着老包儿将笼里的面点装袋。",
		id = 323011048
	},
	[323011049] = {
		speaker = "定远",
		prefab_name = "10163ui_story",
		content = "光盯人家，不知道上去说两句话？",
		id = 323011049
	},
	[323011050] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "唉……有啥好说的……回来再说吧，到时候风风光光的。",
		id = 323011050
	},
	[323011051] = {
		speaker = "",
		prefab_name = "",
		content = "扯了两下当归腰封的磁吸扣，定远不咸不淡地笑了一声，回头迎上拎着一只大油纸袋的老包儿。",
		id = 323011051
	},
	[323011052] = {
		speaker = "包子铺店主",
		prefab_name = "",
		content = "老样子，回来再算钱。",
		id = 323011052
	},
	[323011053] = {
		speaker = "定远",
		prefab_name = "10163ui_story",
		content = "德行……欠不了你的。",
		id = 323011053
	},
	[323011054] = {
		speaker = "",
		prefab_name = "",
		content = "定远接过油纸袋，塞到当归怀里，然后摸出一枚钢镚儿丢给老包儿。两个老头儿默契地碰了个拳头，没再说什么。",
		id = 323011054
	},
	[323011055] = {
		speaker = "",
		prefab_name = "",
		content = "定远朝当归挥挥手，后者端正了神色，师徒俩汇进沿街北行稀稀拉拉的队伍里，去往钟声传来的方向。",
		id = 323011055
	},
	[323011056] = {
		speaker = "",
		prefab_name = "",
		content = "城里每一段北行的路，终点都是那座朝向北方的高耸城关。挂在城门楼上的铜钟还在余响中摇晃，墙下的校场已经聚起了一支万人有余的军队。",
		id = 323011056
	},
	[323011057] = {
		speaker = "",
		prefab_name = "",
		content = "冬风在开阔的校场上通行无阻，像是无声的军鼓，擂在树叶、旗帜与战士们的衣甲上。",
		id = 323011057
	},
	[323011058] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "天冷啊。",
		id = 323011058
	},
	[323011059] = {
		speaker = "",
		prefab_name = "",
		content = "年迈的将军坐在点将台中央，看上去没什么架子，但也没人主动来打扰他。看着校场上的士兵越聚越多，他忍不住这样感慨了一句。",
		id = 323011059
	},
	[323011060] = {
		speaker = "",
		prefab_name = "",
		content = "身边的文武官员都看向杜仲，他只好摆手表示这不是什么军令，正好远远看见定远领着当归，杜仲松了口气，招招手让他们过来。",
		id = 323011060
	},
	[323011061] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "拜见将军！",
		id = 323011061
	},
	[323011062] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "嗯……嗯？你把令旗给他了？",
