	},
	[323011065] = {
		speaker = "",
		prefab_name = "",
		content = "杜仲朝当归点点头，然后招呼一位武官带当归去登记职务。定远正要跟着走，却被杜仲叫住。",
		id = 323011065
	},
	[323011066] = {
		speaker = "定远",
		prefab_name = "10163ui_story",
		content = "有什么指示，将军？",
		id = 323011066
	},
	[323011067] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "没什么指示……要不听哥一句劝，你回去吧。",
		id = 323011067
	},
	[323011068] = {
		speaker = "定远",
		prefab_name = "10163ui_story",
		content = "……不是，你咋现在说这个嘛？说好的自愿报名呢？",
