	},
	[323011069] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "是自愿。你不来不也是「自愿」？",
		id = 323011069
	},
	[323011070] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "这回要去「泰泽」。那是「大荒绝通」之前都没人去过的地方，天知道有什么牛鬼蛇神？",
		id = 323011070
	},
	[323011071] = {
		speaker = "定远",
		prefab_name = "10163ui_story",
		content = "都打一辈子仗了，还怕这？",
		id = 323011071
	},
	[323011072] = {
		speaker = "定远",
		prefab_name = "10163ui_story",
		content = "从咱们那时候打过来的还剩几个？我没别的本事，就是命硬。",
		id = 323011072
	},
	[323011073] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "你也知道没剩几个了。要都打光了，大荒谁还记得虚恒长啥样？",
		id = 323011073
	},
	[323011074] = {
		speaker = "",
		prefab_name = "",
		content = "定远没说话，嘴角绷着，显然还没改主意。杜仲叹了口气，像是见惯了定远这副表情，没继续劝，背着手看向台下乌泱泱的兵甲。",
		id = 323011074
	},
	[323011075] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "你说你，不想回家歇着，还找个后生接班干嘛？",
		id = 323011075
	},
	[323011076] = {
		speaker = "定远",
		prefab_name = "10163ui_story",
		content = "……谁让咱们是人类。",
		id = 323011076
	},
	[323011077] = {
		speaker = "定远",
		prefab_name = "10163ui_story",
		content = "就算不想回去，就算战场上命再硬，到底也会死的。",
