	},
	[323011078] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "……",
		id = 323011078
	},
	[323011079] = {
		speaker = "定远",
		prefab_name = "10163ui_story",
		content = "死之前，咱们还回得去么？",
		id = 323011079
	},
	[323011080] = {
		speaker = "杜仲",
		prefab_name = "10167ui_story",
		content = "先活过这一仗再说。",
		id = 323011080
	},
	[323011081] = {
