		prefab_name = "",
		content = "士兵们都认得定远，接他入队。他没往队伍前面走，仍吊在最后，回头看了一眼。",
		id = 323011095
	},
	[323011096] = {
		speaker = "",
		prefab_name = "",
		content = "蜿蜒的队伍占满了北去的官道，那块「燕沂」的门匾只有队伍最末的他看得清晰。",
		id = 323011096
	},
	[323011097] = {
		speaker = "定远",
		prefab_name = "10163ui_story",
		content = "天真冷啊。",
		id = 323011097
	},
	[323011098] = {
		speaker = "",
		prefab_name = "",
		content = "第三通钟响，缓缓闭合的城门遮住了城内熟悉的光景。定远回过头，眼里不再有南边。",
