	},
	[323021005] = {
		speaker = "",
		prefab_name = "",
		content = "不同于景区用平整的砖石木板甚至塑胶沥青铺设好的山路，这条所谓的路只是清掉植被，再用土石简单夯实而已，走起来着实费劲。",
		id = 323021005
	},
	[323021006] = {
		speaker = "我",
		prefab_name = "",
		content = "十点要回四方院跟良工集团开会。现在八点多了，我们还在南交的荒山里打转。",
		id = 323021006
	},
	[323021007] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "安心安心，山人记着时间呢。就快到山顶了。",
		id = 323021007
	},
	[323021008] = {
		speaker = "我",
		prefab_name = "",
		content = "山顶有什么？",
