	},
	[323021085] = {
		speaker = "我",
		prefab_name = "",
		content = "走了这么久能不喘吗？",
		id = 323021085
	},
	[323021086] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "哈哈，这就是这条山道的精妙之处啊。机关设在临近山巅的位置，让人以为自己累了，实则是着了道，徘徊难前。",
		id = 323021086
	},
	[323021087] = {
		speaker = "我",
		prefab_name = "",
		content = "机关？静督山？不会又是你——",
