	},
	[323022021] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "可世间哪有无缺之法？无论当年先生建起四方院，还是如今五岛搬迁提上日程，都是因时制宜，当变则变。",
		id = 323022021
	},
	[323022022] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "天通引擎没法长久使用。就算没有图灵作乱，五岛迟早要搬回下界。晚辈那两成心力，迟早也得交代出去。",
		id = 323022022
	},
	[323022023] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "旸山也是一样，无论有没有轩辕计划，画境里的凶物，总不能镇一辈子。",
		id = 323022023
	},
	[323022024] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "哼，若是张口闭口就能消灭，吾何须拖到现在？",
		id = 323022024
	},
	[323022025] = {
		speaker = "我",
		prefab_name = "",
		content = "你们说的是「混沌」？",
		id = 323022025
	},
	[323022026] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "人在艾因索菲，虚恒的事倒是知道得不少。",
		id = 323022026
	},
	[323022027] = {
		speaker = "我",
		prefab_name = "",
		content = "来虚恒之前查过一些关于大荒和荒兽的事。不过深空之眼收录的情报也不多……",
		id = 323022027
	},
	[323022028] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "是么，那就好解释了。混沌也有记载么？",
		id = 323022028
	},
	[323022029] = {
		speaker = "我",
		prefab_name = "",
		content = "提到不多……我只听说过「四凶之乱」，四只高危荒兽什么的……",
		id = 323022029
	},
	[323022030] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "不错，穷奇、饕餮、梼杌……还有就是这混沌。",
		id = 323022030
	},
	[323022031] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "混沌无形无相，没料到大荒绝通前它就溜进了虚恒，幸好吾发现及时将它封印，才没酿成灾祸。",
		id = 323022031
	},
	[323022032] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "但封印毕竟不是长久之计……也莫怪晚辈絮叨。",
		id = 323022032
	},
	[323022033] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "前辈，如今「轩辕计划」在即，这位#{nickname}#便是代表深空之眼前来协助。今日一同上山拜访，就为知会前辈一声。",
		id = 323022033
	},
	[323022034] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "如果消灭混沌有任何需要，不止四方院，深空之眼也会尽力提供协助。",
		id = 323022034
	},
	[323022035] = {
		speaker = "我",
		prefab_name = "",
		content = "？",
		id = 323022035
	},
	[323022036] = {
		speaker = "",
		prefab_name = "",
		content = "我茫然地看向孟章，努力回忆着我们是不是达成过类似的协议，结果自然是没有。我终于明白过来，他不告诉我上山的目的，为的就是这一手先斩后奏。",
		id = 323022036
	},
	[323022037] = {
		speaker = "我",
		prefab_name = "",
		content = "（这种事本来我就不会拒绝吧……给我个惊吓寻开心吗？）",
		id = 323022037
	},
	[323022038] = {
		speaker = "",
		prefab_name = "",
		content = "注意到我的目光，孟章郑重其事地朝我点了点头，像是拉着我就我们之间并不存在的共识表个决心。",
		id = 323022038
	},
	[323022039] = {
		speaker = "我",
		prefab_name = "",
		content = "……处理特殊类型的敌人，我和深空之眼都有丰富的经验。如果前辈有需要，我可以联系总部看看能不能调些人手来协助处理。",
		id = 323022039
	},
	[323022040] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "吾知道你们的本事，但还是那句话，这不是张口闭口就能去办的事，否则吾早动手了。",
		id = 323022040
	},
	[323022041] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "奥丁也好，梵天也好，庚辰曾找过她们……还有科尔盖，都拿不出更好的主意。你们就别枉言相帮了。",
		id = 323022041
	},
	[323022042] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "回去吧，不必操旸山的心，吾自有主意。",
		id = 323022042
	},
	[323022043] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "前辈果真有办法？",
		id = 323022043
	},
	[323022044] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "你若翻过四方院里那些典籍，就该知道「天通术」是什么。吾这些年守在宫里，可不是成日游山玩水。",
		id = 323022044
	},
	[323022045] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "但现在机缘未到，你莫再催促，等着便是。",
		id = 323022045
	},
	[323022046] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "守虚恒上下，解荒兽之危，多仰仗前辈。",
		id = 323022046
	},
	[323022047] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "油嘴滑舌……",
		id = 323022047
	},
	[323022048] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "前辈宽心，就算万事顺利，搬空五岛少说也得一年。在那之前，天通引擎不会关停，旸山自然也就无事……",
		id = 323022048
	},
	[323022049] = {
		speaker = "我",
		prefab_name = "",
		content = "……说起民众，有件事不知道方不方便问。",
		id = 323022049
	},
	[323022050] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "只有方不方便答，没有方不方便问。",
		id = 323022050
	},
	[323022051] = {
		speaker = "我",
		prefab_name = "",
		content = "我听说大荒绝通的时候，有不少人留在大荒……那不是与世隔绝，还要面对荒兽的威胁吗？为什么要这么做？",
		id = 323022051
	},
	[323022052] = {
		speaker = "",
		prefab_name = "",
		content = "听到这个问题，孟章和羲和脸色都变了变，旋即露出无奈而歉然的表情。",
		id = 323022052
	},
	[323022053] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "这事……说来惭愧。",
		id = 323022053
	},
	[323022054] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "四凶之乱过后，虽然荒兽元气大伤，但若放任它们在大荒休养生息，难保不是养虎为患。",
		id = 323022054
	},
	[323022055] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "所以边军十万将士请求驻守大荒。荒兽不除，边军不归。",
		id = 323022055
	},
	[323022056] = {
		speaker = "",
		prefab_name = "",
		content = "我听得愣住了，难以想象那是一种怎样的觉悟和勇气。如果荒兽和视骸一样源源不绝，那留在大荒就几乎等于投身一场永无止尽的战争。",
		id = 323022056
	},
	[323022057] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "当然了，我们也没打算放弃边军，原本打算等处理完云歌石的问题，就把大荒接回虚恒……",
		id = 323022057
	},
	[323022058] = {
		speaker = "我",
		prefab_name = "",
		content = "处理完云歌石的问题……你说的是「轩辕计划」？",
		id = 323022058
	},
	[323022059] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "是的。令民众归乡是其一；确保后方安稳，夺回大荒是其二。",
		id = 323022059
	},
	[323022060] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "若非此事非同小可，晚辈也是万万不敢上山叨扰的。",
		id = 323022060
	},
	[323022061] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "答话就答话，拐弯抹角做什么……",
		id = 323022061
	},
	[323022062] = {
		speaker = "",
		prefab_name = "",
		content = "孟章与羲和又说起一些虚恒地方上的事。我插不上话，只好打量起若木宫。这山间宫阙虽然外观气派，内饰却十分简朴。",
		id = 323022062
	},
	[323022063] = {
		speaker = "",
		prefab_name = "",
		content = "桌椅都是实木打制，墙上的字画卷轴与铜镜宝剑，看上去都有些年头，表面却不染纤尘，整座殿内颇具清修的氛围。",
		id = 323022063
	},
	[323022064] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "……那晚辈就先告辞了。",
		id = 323022064
	},
	[323022065] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "嗯。你们若是见到金乌，让她早些回来。再荒废功课，吾要罚她禁足了。",
		id = 323022065
	},
	[323022066] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "晚辈会留心。",
		id = 323022066
	},
	[323022067] = {
		speaker = "我",
		prefab_name = "",
		content = "她身上没终端吗？",
		id = 323022067
	},
	[323022068] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "山里修行，鲜有人联系。她只拿终端当个漫画书用，平时出门并不携带。",
		id = 323022068
	},
	[323022069] = {
		speaker = "",
		prefab_name = "",
		content = "羲和身上确实没有佩戴终端。我摸摸鼻子，没再打探她们师徒的规矩，跟随孟章一同离开了若木宫。",
		id = 323022069
	},
	[323022070] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "……",
		id = 323022070
	},
	[323022071] = {
		speaker = "",
		prefab_name = "",
		content = "背手站在宫门前，羲和远远看着两位访客消失在山腰的密林间，转身回到屋里。",
		id = 323022071
	},
	[323022072] = {
		speaker = "",
		prefab_name = "",
		content = "她抬起手，捏了个法诀，指尖燃起一缕明火。随着她操控神能以某种不同于神能回路的方式运转，这缕火焰的温度越来越高，蕴含的神能也愈发浓郁。",
		id = 323022072
	},
	[323022073] = {
		speaker = "",
		prefab_name = "",
		content = "渐渐地，火焰燃烧的幅度越来越小，内外色差也越来越小，仿佛开始向着某种可以被称之为「燃烧」的原始形态转化。",
		id = 323022073
	},
	[323022074] = {
		speaker = "",
		prefab_name = "",
		content = "但当羲和皱起眉头时，这种转化戛然而止，火焰依旧是火焰，卡在人们通常认知的「火焰」范畴内。",
		id = 323022074
	},
	[323022075] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "事到半途，终究是要有个了结吗？",
		id = 323022075
	},
	[323022076] = {
		speaker = "",
		prefab_name = "",
		content = "羲和长长叹了口气，屈指一弹，指尖的火焰落到一柄挂在墙上的宝剑表面，像是被它吸收，转眼间便没了踪影。",
		id = 323022076
	},
	[323022077] = {
		speaker = "",
		prefab_name = "",
		content = "她盯着那柄宝剑良久，摇摇头，拂手关上宫门。",
		id = 323022077
	},
	[323031001] = {
		speaker = "我",
		prefab_name = "",
		content = "你约的是十点整吧？",
		id = 323031001
	},
	[323031002] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "老爷子忙，再等等呗。",
		id = 323031002
	},
	[323031003] = {
		speaker = "",
		prefab_name = "",
		content = "与孟章一道火急火燎地赶回四方院，好歹在十点前坐上了会客厅的椅子。可又过了十分钟，并不见人来访。",
		id = 323031003
	},
	[323031004] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "正好，这趟去旸山，还没听你说说感想呢。",
		id = 323031004
	},
	[323031005] = {
		speaker = "",
		prefab_name = "",
		content = "孟章这人不可信",
		id = 323031005
	},
	[323031006] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "哈哈，你看结果，是不是山也爬了，事儿也聊了？",
		id = 323031006
	},
	[323031007] = {
		speaker = "我",
		prefab_name = "",
		content = "不能早点跟我商量么？",
		id = 323031007
	},
	[323031008] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "旸山与混沌的情况我也知之甚少，与其咱俩空聊徒增烦恼，不如直接找当事人问问。",
		id = 323031008
	},
	[323031009] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "听说是金乌的老师，以为是个仙风道骨的老人家？",
		id = 323031009
	},
	[323031010] = {
		speaker = "我",
		prefab_name = "",
		content = "都是修正者，倒不至于以为是老人家……只是没想到看上去比金乌还小。",
		id = 323031010
	},
	[323031011] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "哈哈，不可以貌取人啊。她可是纪元之初就苏醒的前辈，无论实力还是资历，都不是我这种后生晚辈可以比的。",
		id = 323031011
	},
	[323031012] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "扪心自问，山人不算诈你吧？你来之前，可说好了，「轩辕计划相关之事，都在协商范围内」。",
		id = 323031012
	},
	[323031013] = {
		speaker = "我",
		prefab_name = "",
		content = "是这么说没错……",
		id = 323031013
	},
	[323031014] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "那就是了。那混沌的凶险，万万不可低估，羲和前辈能力非凡，在旸山中镇压数十年尚且不能将它消灭，你就知道是个多严重的祸患了。",
		id = 323031014
	},
	[323031015] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "此番你我去旸山表个态，看似没做什么，要说重要性，眼前这场会议也不过如此。",
		id = 323031015
	},
	[323031016] = {
		speaker = "我",
		prefab_name = "",
		content = "……既然已经点头了，那这件事就算我一份，就像你说的，深空之眼会尽力提供协助。",
		id = 323031016
	},
	[323031017] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "不怕你食言。不过羲和前辈看上去已有打算，你我也不必太过操心了，哈哈。",
		id = 323031017
	},
	[323031018] = {
		speaker = "我",
		prefab_name = "",
		content = "不说那么远，还得操心别的事吧？你还答应帮忙找金乌呢，怎么个找法？",
		id = 323031018
	},
	[323031019] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "「留心」的意思怎么都不是「找」吧……回来的路上我派人查过，总之不在五岛。",
		id = 323031019
	},
	[323031020] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "怎么，你找她有事？",
		id = 323031020
	},
	[323031021] = {
		speaker = "",
		prefab_name = "",
		content = "我摇摇头，没有细究这个问题，只是隐约感觉羲和对金乌在外这件事的态度有些微妙。",
		id = 323031021
	},
	[323031022] = {
		speaker = "",
		prefab_name = "",
		content = "我端起桌上的茶水，入口有些凉了，正寻思还要等待多久，门外走廊终于传来了脚步声。",
		id = 323031022
	},
	[323031023] = {
		speaker = "",
		prefab_name = "",
		content = "我与孟章站起身，只见几位服饰统一商务打扮的人士走进门，个个精神饱满，反倒是为首的老人愁容满面。见我与孟章已候在会客厅里，他才恢复了些精神。",
		id = 323031023
	},
	[323031024] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "舆昊老板，这位便是深空之眼的商务代表，#{nickname}#，全权负责这次洽谈。",
		id = 323031024
	},
	[323031025] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "年轻有为啊。这么大的事，我还以为也会派一支代表团来。",
		id = 323031025
	},
	[323031026] = {
		speaker = "我",
		prefab_name = "",
		content = "都是同事肯信任。要说年轻有为，您三十五岁接管良工集团，那才是让人钦佩。",
		id = 323031026
	},
	[323031027] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "哎，咳咳……特殊时期赶鸭子上架罢了……",
		id = 323031027
	},
	[323031028] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "得了，你们俩一句不提迟到的事，还得我自己谢罪。客套话改天留到饭桌上说吧，今天抓紧时间谈正事。",
		id = 323031028
	},
	[323031029] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "公事是正事，私事也是正事，不知舆昊老板在愁什么呢？",
		id = 323031029
	},
	[323031030] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "家事罢了……",
		id = 323031030
	},
	[323031031] = {
		speaker = "",
		prefab_name = "",
		content = "自家员工在旁，舆昊似乎有些避讳，可看着孟章，他神情纠结了一阵，最后还是开了口。",
		id = 323031031
	},
	[323031032] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "孟章代理，你认识我那孙女重明吧？",
		id = 323031032
	},
	[323031033] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "认得，在茶馆戏院古玩店都遇到过。",
		id = 323031033
	},
	[323031034] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "是了，都这么说。这孩子吧，打小就皮，喜欢大街小巷到处溜达，跟着人学杂耍，学个一招半式就要表演给我看，又怕我管教她，出门总不跟我说。",
		id = 323031034
	},
	[323031035] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "这几天我忙着看玉京旧城二期工程，去朔方的子公司那儿出了趟差，回来一看，这孩子又溜出去了。",
		id = 323031035
	},
	[323031036] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "我问了一圈，结果说她跟着一支工程队下地去了。现在不知道人去了哪儿，通讯也不接……",
		id = 323031036
	},
	[323031037] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "终端只要开机就能定位吧？",
		id = 323031037
	},
	[323031038] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "唉，坏就坏在这儿，警察都定位不到啊。八成是跑到哪个没信号的荒山野岭探险去了。",
		id = 323031038
	},
	[323031039] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "你们说这孩子怎么就这么不让人省心呢？坐上书桌，脑筋是好使的，让她学的也都学了。学完以后呢，心思还是收不回来的。",
		id = 323031039
	},
	[323031040] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "集团里那么多事可以做，她就愣是一件都不感兴趣，成天惦记着茶馆戏院，惦记那些山沟沟……",
		id = 323031040
	},
	[323031041] = {
		speaker = "",
		prefab_name = "",
		content = "舆昊开了话匣，摇头叹气诉苦不迭，倒是孟章不接话了。我看了孟章一眼，却发现他一副似笑非笑的表情。",
		id = 323031041
	},
	[323031042] = {
		speaker = "我",
		prefab_name = "",
		content = "（……这家伙不会又在装傻吧？）",
		id = 323031042
	},
	[323031043] = {
		speaker = "",
		prefab_name = "",
		content = "舆昊说着说着，突然捶着胸口咳嗽了几声，似乎身体不太好。被自己打断，他才意识到跑题了，朝我们歉然地笑笑，让下属开始洽谈合作的事宜。",
		id = 323031043
	},
	[323031044] = {
		speaker = "",
		prefab_name = "",
		content = "商务谈判没有太多可以说道的地方，过程很顺利，唯一可以称作挑战的只有签字环节——签到最后我都快不认识自己的名字了。",
		id = 323031044
	},
	[323031045] = {
		speaker = "",
		prefab_name = "",
		content = "大概是急着继续找孙女，谈判结束后舆昊没有多作停留。",
		id = 323031045
	},
	[323031046] = {
		speaker = "",
		prefab_name = "",
		content = "我和孟章一路将良工集团的代表团送出四方院。看着车队远去，我终于忍不住了。",
		id = 323031046
	},
	[323031047] = {
		speaker = "我",
		prefab_name = "",
		content = "你笑什么？",
		id = 323031047
	},
	[323031048] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "我不一直是这个表情嘛？",
		id = 323031048
	},
	[323031049] = {
		speaker = "我",
		prefab_name = "",
		content = "啧，少装傻，你是真笑还是假笑我看得出来。舆昊老板说他孙女失踪，你分明是真想笑。",
		id = 323031049
	},
	[323031050] = {
		speaker = "我",
		prefab_name = "",
		content = "不说荒山野岭别的危险，不要忘了下界还有视骸。再说舆昊老板会上咳嗽了好几回，身体显然不好，让他担心的事，有什么可笑的？",
		id = 323031050
	},
	[323031051] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "唔，现在下地干活的工程队都有修正者暗中保护，科尔盖、四方院、天禄贸易……都出了人手。",
		id = 323031051
	},
	[323031052] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "如果是跟着工程队下去的，有人离队，他们都会上报。",
		id = 323031052
	},
	[323031053] = {
		speaker = "我",
		prefab_name = "",
		content = "……所以你接到过报告？你知道重明去哪儿了？",
		id = 323031053
	},
	[323031054] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "没有，因为重明自己就是修正者啊。",
		id = 323031054
	},
	[323031055] = {
		speaker = "我",
		prefab_name = "",
		content = "……",
		id = 323031055
	},
	[323031056] = {
		speaker = "我",
		prefab_name = "",
		content = "那没事了。",
		id = 323031056
	},
	[323031057] = {
		speaker = "",
		prefab_name = "",
		content = "我揉了揉眉心，感觉自己可能是见多了修正者组织，思维有些僵化。",
		id = 323031057
	},
	[323031058] = {
		speaker = "我",
		prefab_name = "",
		content = "……所以，重明是修正者，但没有加入任何组织。她就待在良工集团生活，舆昊老板也不知道他孙女是修正者。",
		id = 323031058
	},
	[323031059] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "抱养来的孙女，能这样视如己出，难能可贵啊。",
		id = 323031059
	},
	[323031060] = {
		speaker = "我",
		prefab_name = "",
		content = "听上去又是个拖得越久越麻烦的「家事」。",
		id = 323031060
	},
	[323031061] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "船到桥头自然直嘛。",
		id = 323031061
	},
	[323031062] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "与其担心重明，倒是你让我大开眼界。那么多生意场上的事情，从容不迫对答如流，难不成你失忆前是个做生意的？",
		id = 323031062
	},
	[323031063] = {
		speaker = "我",
		prefab_name = "",
		content = "我出门买东西都不讲价，还做生意呢……没那么玄乎。",
		id = 323031063
	},
	[323031064] = {
		speaker = "",
		prefab_name = "",
		content = "关于我过去的情报，现在已经被列为机密，只有深空之眼和科尔盖里的少数高层知道，外加一个梵天。",
		id = 323031064
	},
	[323031065] = {
		speaker = "",
		prefab_name = "",
		content = "所以听到孟章开这样的玩笑，我也只能在心里暗叹一声，忽然觉得自己与孟章有了几分相似，然后打着哈哈装傻，指了指自己的耳机。",
		id = 323031065
	},
	[323031066] = {
		speaker = "我",
		prefab_name = "",
		content = "谈生意嘛，无非就是两边都觉得自己赚了，互相围着核心利益打转，你好我好。至于良工想要什么——",
		id = 323031066
	},
	[323031067] = {
		speaker = "我",
		prefab_name = "",
		content = "整个深空之眼都是我的顾问，你说呢。",
		id = 323031067
	},
	[323041001] = {
		speaker = "",
		prefab_name = "",
		content = "印象里，每次经过鲤港外的这座桥，都有风来。",
		id = 323041001
	},
	[323041002] = {
		speaker = "",
		prefab_name = "",
		content = "行过桥上，穿过桥下，吹净栏杆，吹皱洛泉。",
		id = 323041002
	},
	[323041003] = {
		speaker = "？？？",
		prefab_name = "",
		content = "还没睡么？",
		id = 323041003
	},
	[323041004] = {
		speaker = "",
		prefab_name = "",
		content = "灯影与月影一同落在河面上，明亮的白里透着浅黄，被水波拆成粼粼的点与线，模糊成相似的形状，远处近处仿佛互为倒影。",
		id = 323041004
	},
	[323041005] = {
		speaker = "我",
		prefab_name = "",
		content = "庚辰……",
		id = 323041005
	},
	[323041006] = {
		speaker = "",
		prefab_name = "",
		content = "记忆中，我并未与庚辰一同来过这里。长桥、奔流、寂夜、浮光……一切相关的画面，都不曾与她联系到一起。",
		id = 323041006
	},
	[323041007] = {
		speaker = "",
		prefab_name = "",
		content = "我收回远眺的视线，对上她无论何时都认真到有些拙朴的眼神，内心所有释放于眼前这片空旷的躁动——从不安到激奋——都被冲刷得平静。",
		id = 323041007
	},
	[323041008] = {
		speaker = "",
		prefab_name = "",
		content = "平静，像是一根被按住的琴弦，忽得不再发出声音。但我们不会立刻松开它，只因余声仍在我们脑海中盘桓。",
		id = 323041008
	},
	[323041009] = {
		speaker = "庚辰",
		prefab_name = "1076ui_story",
		content = "许久不见。",
		id = 323041009
	},
	[323041010] = {
		speaker = "我",
		prefab_name = "",
		content = "……",
		id = 323041010
	},
	[323041011] = {
		speaker = "庚辰",
		prefab_name = "1076ui_story",
		content = "夜半来此，是有心事。",
		id = 323041011
	},
	[323041012] = {
		speaker = "我",
		prefab_name = "",
		content = "我不知道……太多问题，解决了又出现。接触的越多，未知就越多。",
		id = 323041012
	},
	[323041013] = {
		speaker = "我",
		prefab_name = "",
		content = "从夏什瓦特回去以后，风平浪静了小半年，清闲归清闲，但要紧的事全都没进展，这样停滞真的好吗……",
		id = 323041013
	},
	[323041014] = {
		speaker = "庚辰",
		prefab_name = "1076ui_story",
		content = "你认为，什么算「要紧的事」？",
		id = 323041014
	},
	[323041015] = {
		speaker = "",
		prefab_name = "",
		content = "搞清楚我来盖亚的目的",
		id = 323041015
	},
	[323041016] = {
		speaker = "庚辰",
		prefab_name = "1076ui_story",
		content = "……",
		id = 323041016
	},
	[323041017] = {
		speaker = "我",
		prefab_name = "",
		content = "困难，但必须去做，而且一定要有结果，甚至不能失败……大概就是这样的事吧。",
		id = 323041017
	},
	[323041018] = {
		speaker = "庚辰",
		prefab_name = "1076ui_story",
		content = "不必将它们全扛在自己身上。",
		id = 323041018
	},
	[323041019] = {
		speaker = "我",
		prefab_name = "",
		content = "你来跟我说这个吗……",
		id = 323041019
	},
	[323041020] = {
		speaker = "",
		prefab_name = "",
		content = "我只能苦笑。她就站在我面前，「许久不见」，却始终隔着一段触碰不及的距离，就像河面上的灯影月影。",
		id = 323041020
	},
	[323041021] = {
		speaker = "庚辰",
		prefab_name = "1076ui_story",
		content = "#{nickname}#，古往今来，有人能通晓一切，执掌一切吗？",
		id = 323041021
	},
	[323041022] = {
		speaker = "",
		prefab_name = "",
		content = "没有",
		id = 323041022
	},
	[323041023] = {
		speaker = "庚辰",
		prefab_name = "1076ui_story",
		content = "有事物能永存于世、亘古不变，又有道理或者办法，能放之宇宙而皆准吗？",
		id = 323041023
	},
	[323041024] = {
		speaker = "",
		prefab_name = "",
		content = "没有",
		id = 323041024
	},
	[323041025] = {
		speaker = "庚辰",
		prefab_name = "1076ui_story",
		content = "即便知道一切终将改变，你仍不甘随波逐流，这又是为什么？",
		id = 323041025
	},
	[323041026] = {
		speaker = "我",
		prefab_name = "",
		content = "……因为人类就是这样得以存活的，总是期望能做到更多，再去实现其中能够实现的部分。",
		id = 323041026
	},
	[323041027] = {
		speaker = "庚辰",
		prefab_name = "1076ui_story",
		content = "嗯。天地无全功，万物无全用。我们之于他人他物，元是两面，能够期许的圆满，也不过如水映月。",
		id = 323041027
	},
	[323041028] = {
		speaker = "庚辰",
		prefab_name = "1076ui_story",
		content = "所以，不必苛责环境，更不必苛责自己。",
		id = 323041028
	},
	[323041029] = {
		speaker = "",
		prefab_name = "",
		content = "庚辰抬起手，系在我衣领下面的玉佩飘然飞出，悬浮在我们中间，表面泛着一层洁白的光辉。",
		id = 323041029
	},
	[323041030] = {
		speaker = "庚辰",
		prefab_name = "1076ui_story",
		content = "早些睡吧，休息好比什么都重要。",
		id = 323041030
	},
	[323041031] = {
		speaker = "",
		prefab_name = "",
		content = "我默默点头，伸出手想要将玉佩拿回，却发现自己无论如何碰不到它。",
		id = 323041031
	},
	[323041032] = {
		speaker = "",
		prefab_name = "",
		content = "我用力地把身子往前探，抬起腿往前走，甚至有了奔跑的念头，可身体只是原地不动，只是在想象那些动作而已。",
		id = 323041032
	},
	[323041033] = {
		speaker = "我",
		prefab_name = "",
		content = "庚辰……",
		id = 323041033
	},
	[323041034] = {
		speaker = "",
		prefab_name = "",
		content = "我伸着手，茫然地抬起头，就在视线短暂飘忽移动的瞬间，有风吹过。行过桥上，穿过桥下，吹散玉佩，吹远了……",
		id = 323041034
	},
	[323041035] = {
		speaker = "我",
		prefab_name = "",
		content = "——！",
		id = 323041035
	},
	[323041036] = {
		speaker = "",
		prefab_name = "",
		content = "熟悉的天花板。几乎每次借住四方院，给我安排的都是这间客房。",
		id = 323041036
	},
	[323041037] = {
		speaker = "",
		prefab_name = "",
		content = "并不意外，在内心深处我比谁都清楚，庚辰没有回来，我们也没有找到她。",
		id = 323041037
	},
	[323041038] = {
		speaker = "我",
		prefab_name = "",
		content = "……",
		id = 323041038
	},
	[323041039] = {
		speaker = "",
		prefab_name = "",
		content = "紧绷的身体开始放松，我慢慢放下伸出被子的手，忽然又产生了微弱的异样感。",
		id = 323041039
	},
	[323041040] = {
		speaker = "",
		prefab_name = "",
		content = "是光照？我应该在没开灯的房间里看清天花板和自己的手吗？不止光照，还有扫过手臂的微弱气流——",
		id = 323041040
	},
	[323041041] = {
		speaker = "我",
		prefab_name = "",
		content = "窗户没关紧？",
		id = 323041041
	},
	[323041042] = {
		speaker = "",
		prefab_name = "",
		content = "我朝窗户的方向扭头看去。",
		id = 323041042
	},
	[323041043] = {
		speaker = "",
		prefab_name = "",
		content = "如我所料，窗户的确没关紧，可我却愣住了，复杂的临场反应让我的身体没能做出任何反应，甚至没能从床上坐起来。",
		id = 323041043
	},
	[323041044] = {
		speaker = "我",
		prefab_name = "",
		content = "你……",
		id = 323041044
	},
	[323041045] = {
		speaker = "",
		prefab_name = "",
		content = "不知名姓的少女站在窗边，单手举着我那半块化清龙云佩，对准夜空中的上弦月，遥作月亮隐去的半边。听到我的声音，她才回过头看向我。",
		id = 323041045
	},
	[323041046] = {
		speaker = "",
		prefab_name = "",
