	},
	[323061041] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "雪山路崎岖难走，记得别费太多体力。你可以在附近找找，说不定有些前人留下的老建筑，遮风避寒也许够用。",
		id = 323061041
	},
	[323061042] = {
