	},
	[323071111] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "……金乌，管理员。",
		id = 323071111
	},
	[323071112] = {
		speaker = "",
		prefab_name = "",
		content = "一旁的重明忽然喊了我们一声，语气似乎有些不安。我们转过头，看到她正一脸茫然地看着终端。",
		id = 323071112
	},
	[323071113] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "我联系不上安保处的乐叔了。",
		id = 323071113
	},
	[323071114] = {
		speaker = "我",
		prefab_name = "",
		content = "会不会关机了？",
		id = 323071114
	},
	[323071115] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "不会的。乐叔是安保处的大队长，要求就是全天待命随叫随到。",
		id = 323071115
	},
	[323071116] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
