	},
	[323071119] = {
		speaker = "",
		prefab_name = "",
		content = "云层上一架小型运输机减速悬停，然后开始缓缓下落，我看了眼机身上四方院的标志，接起通讯。",
		id = 323071119
	},
	[323071120] = {
		speaker = "我",
		prefab_name = "",
		content = "孟章，方便去一趟昭黎山吗？",
