	},
	[323071121] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "方便是方便……怎么回事？飞机扫到你那儿有三个人。",
		id = 323071121
	},
	[323071122] = {
		speaker = "我",
		prefab_name = "",
		content = "我找到金乌和重明了。",
		id = 323071122
	},
	[323071123] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
