	},
	[323081043] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "有魑魅。",
		id = 323081043
	},
	[323081044] = {
		speaker = "我",
		prefab_name = "",
		content = "难道是被视骸……",
		id = 323081044
	},
	[323081045] = {
		speaker = "",
		prefab_name = "",
		content = "我打开弥弥尔系统，果然在前面检测到了骸能反应，眉头一下子皱了起来。",
		id = 323081045
	},
	[323081046] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "管理员小哥，你找地方躲一下吧？",
		id = 323081046
	},
	[323081047] = {
