	},
	[323092005] = {
		speaker = "？？？",
		prefab_name = "1053ui_story",
		content = "那滑头小子还没那么大面子……吾听说了，便来看看。",
		id = 323092005
	},
	[323092006] = {
		speaker = "？？？",
		prefab_name = "1053ui_story",
		content = "原本感应到山里还有一只，跑得倒挺利索。",
