	},
	[323101014] = {
		speaker = "常曦",
		prefab_name = "1053ui_story",
		content = "为何沉默不语？有别的想法么？",
		id = 323101014
	},
	[323101015] = {
		speaker = "",
		prefab_name = "",
		content = "我不知道该说什么。我来虚恒不过两天，「荒兽」就从一个初次听说的概念变成了真切出现在眼前的敌人。",
		id = 323101015
	},
	[323101016] = {
		speaker = "",
		prefab_name = "",
		content = "联想到奥丁糟糕的通讯环境，我不禁打了个寒颤。",
