	},
	[323101017] = {
		speaker = "我",
		prefab_name = "",
		content = "（这预知真有这么邪乎？就不能多说两句吗奥丁！）",
		id = 323101017
	},
	[323101018] = {
		speaker = "",
		prefab_name = "",
		content = "实在不知道接下来会发生什么，我只好硬着头皮往下接话。",
