	},
	[323111027] = {
		speaker = "常曦",
		prefab_name = "1053ui_story",
		content = "吾不是在责怪你。",
		id = 323111027
	},
	[323111028] = {
		speaker = "长琴",
		prefab_name = "",
		content = "工坊一没得罪过人，二没值钱的物什，怎么会招惹这样的祸端？",
