	[323112045] = {
		speaker = "我",
		prefab_name = "",
		content = "再坚持一会儿，四方院的支援就来了。现在搭上谁的命都不划算……",
		id = 323112045
	},
	[323112046] = {
		speaker = "",
		prefab_name = "",
		content = "我捂着脑袋，飞快构思着各种可以拖延时间的方案，一边伸手抓住剑匣的扣带，想将这东西挪远些，以免长琴冲动。",
		id = 323112046
	},
	[323112047] = {
		speaker = "",
		prefab_name = "",
		content = "可还没等我将它提起，那把插在剑匣里的剑忽然自行从环扣中抽出，悬停在我面前。还没等我反应过来，它调转方向，化作一抹无声的流虹，眨眼便冲出了冰窟。",
		id = 323112047
	},
	[323112048] = {
