	[323121036] = {
		speaker = "",
		prefab_name = "",
		content = "常曦将「大荒绝通」的情况简单对望舒说了一遍，看不出望舒听懂了多少。她只是看了眼长琴，目光又移向常曦，在后者身上多停了一会儿，最后摇了摇头。",
		id = 323121036
	},
	[323121037] = {
		speaker = "",
		prefab_name = "",
		content = "就在我们以为她这是在表达拒绝时，她走到我边上，拿剑柄戳了一下我的胳膊。",
		id = 323121037
	},
	[323121038] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "我还记得燕门关的位置。但你们两个去不了，他跟我去。",
		id = 323121038
	},
	[323121039] = {
		speaker = "我",
		prefab_name = "",
		content = "哈？",
		id = 323121039
	},
	[323121040] = {
		speaker = "常曦",
		prefab_name = "1053ui_story",
		content = "望舒道友，为何吾去不了，他却可以？",
