	[323121083] = {
		speaker = "我",
		prefab_name = "",
		content = "等等……出差得汇报一下……",
		id = 323121083
	},
	[323121084] = {
		speaker = "",
		prefab_name = "",
		content = "也许比起眼前未知的情况，向深空之眼的汇报肉眼可见地更让我头疼。休办公室的通讯很快接通，我忍不住咽了口口水。",
		id = 323121084
	},
	[323121085] = {
		speaker = "休",
		prefab_name = "1019ui_story",
		content = "……唉，说吧，又惹什么事了？",
		id = 323121085
