	},
	[323121103] = {
		speaker = "长琴",
		prefab_name = "",
		content = "另有一件事，还望你能帮忙。",
		id = 323121103
	},
	[323121104] = {
		speaker = "我",
		prefab_name = "",
		content = "您说，我能帮就帮。",
		id = 323121104
	},
	[323121105] = {
		speaker = "长琴",
		prefab_name = "",
		content = "这只剑匣，你带上。",
