		id = 323121121
	},
	[323121122] = {
		speaker = "",
		prefab_name = "",
		content = "虽然不知道为什么我拿本剑谱有什么用，但听得出长琴是一番好意，我就没有拒绝。",
		id = 323121122
	},
	[323121123] = {
		speaker = "我",
