	},
	[323131027] = {
		speaker = "羲和",
		prefab_name = "1053ui_story",
		content = "……他是人类，还是个门外汉。",
		id = 323131027
	},
	[323131028] = {
		speaker = "长琴",
		prefab_name = "",
		content = "是啊，我也觉得古怪。可是百年间再没第三个人能打开承钧。",
		id = 323131028
	},
	[323131029] = {
		speaker = "长琴",
		prefab_name = "",
		content = "要说骥服盐车，承钧于我更贴切。我虽能用它为神剑「调律」，但以音律理解神剑之「理」，夸一句是另辟蹊径，贬一句就是歪门邪道了。",
		id = 323131029
	},
	[323131030] = {
		speaker = "羲和",
		prefab_name = "1053ui_story",
		content = "你造的东西，你不知道怎么用？",
		id = 323131030
	},
	[323131031] = {
		speaker = "长琴",
		prefab_name = "",
		content = "前辈也说了，神剑是权钥，一看相性，二看心性。\n故而理解神剑之理，要懂的不止有剑，还有执剑的人。",
		id = 323131031
	},
	[323131032] = {
		speaker = "长琴",
		prefab_name = "",
		content = "习剑者大多只认手里的剑。他虽是人类，又是门外汉……说不准正该如此呢？",
		id = 323131032
	},
	[323131033] = {
		speaker = "",
		prefab_name = "",
		content = "冰窟外传来飞机着陆的喷流噪声。不多时，一道人影匆匆忙忙跑进来，朝长琴与羲和做了个揖，而后急迫地张望了一圈。",
		id = 323131033
	},
	[323131034] = {
		speaker = "孟章",
		prefab_name = "1071ui_story",
		content = "……#{nickname}#呢？",
