	},
	[323131036] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "都回四方院了，你这当家的，少安毋躁。",
		id = 323131036
	},
	[323131037] = {
		speaker = "",
		prefab_name = "",
		content = "羲和不紧不慢地喝了口茶。孟章却仍黑着脸，嘴角紧绷，在会客厅内来回踱步。",
		id = 323131037
	},
	[323131038] = {
		speaker = "孟章",
