	},
	[323141001] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "老师~老师，乌回来啦！",
		id = 323141001
	},
	[323141002] = {
		speaker = "",
		prefab_name = "",
		content = "金乌双手扒着门框，探出脑袋，朝屋里张望了几眼，却没听到回应。她先是松了口气，而后扁了扁嘴，跨进若木宫的大门。",
		id = 323141002
	},
	[323141003] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "原来老师也出门了。早知道在城里多玩一会儿了……",
		id = 323141003
	},
	[323141004] = {
		speaker = "",
		prefab_name = "",
		content = "回头望着山道愣了会儿神，金乌终究是没敢再跑下山去，正觉得有些无聊，忽然听到自己的屋子里传出一阵振动。",
		id = 323141004
	},
	[323141005] = {
