	},
	[323191024] = {
		speaker = "相柳",
		prefab_name = "",
		content = "我居无定所，也不需要定所，大荒也好，虚恒也罢，都只不过是个去处而已。",
		id = 323191024
	},
	[323191025] = {
		speaker = "相柳",
		prefab_name = "",
		content = "不像你们，把自己栓在一亩三分地里，做点什么事都瞻前顾后，彼此拖累，有意思么？",
		id = 323191025
	},
	[323191026] = {
		speaker = "羲和",
		prefab_name = "1053ui_story",
		content = "你将自己摆在与一切敌对的位置，用这种对立束缚自己，又何来的自由？",
