	},
	[323191027] = {
		speaker = "相柳",
		prefab_name = "",
		content = "呵，要不怎么说你们养尊处优惯了……",
		id = 323191027
	},
	[323191028] = {
		speaker = "相柳",
		prefab_name = "",
		content = "躲在这个小角落里，一群井底之蛙，根本不知道「世界」是什么东西。",
		id = 323191028
	},
	[323191029] = {
		speaker = "相柳",
		prefab_name = "",
		content = "你想要有的选，你想要跟「它」谈什么和谐，「它」想给你机会吗？它不想。它只把我们当成恭顺又弱小的蝼蚁。",
		id = 323191029
	},
	[323191030] = {
		speaker = "",
		prefab_name = "",
		content = "相柳越说越激动，忽然克制抬了一下手，打断了自己的宣泄，然后闭上眼睛，用力按住自己的太阳穴。",
		id = 323191030
	},
	[323191031] = {
		speaker = "羲和",
		prefab_name = "1053ui_story",
		content = "……这又是何意？",
		id = 323191031
	},
	[323191032] = {
		speaker = "相柳",
