	},
	[323221041] = {
		speaker = "羲和",
		prefab_name = "1053ui_story",
		content = "「天通术」。",
		id = 323221041
	},
	[323222001] = {
		speaker = "",
		prefab_name = "",
		content = "分不清相柳这具化身是逃走了，还是在羲和的剑下灰飞烟灭了，但我看向孟章和羲和，在他们脸上都看到了稍显放松的表情。",
		id = 323222001
	},
	[323222002] = {
