		prefab_name = "",
		content = "但钢铁和水泥替换不了脆弱皮囊。当动物回到动物原本的居所。",
		id = 323501004
	},
	[323501005] = {
		speaker = "",
		prefab_name = "",
		content = "人类、泥土和鲜血，三者的关系从未被改变。",
		id = 323501005
	},
	[323501006] = {
		speaker = "边军军士甲",
		prefab_name = "10162ui_story",
		content = "快！再靠近些，把畜牲引过来，别让它们靠近农区！",
		id = 323501006
	},
	[323501007] = {
		speaker = "",
		prefab_name = "",
		content = "荒原之上，十几辆摩托排着箭头状的队形疾驰，飞过一个小坡，落地后再次加速，向不远处几只游荡的荒兽驶去。",
		id = 323501007
	},
	[323501008] = {
		speaker = "",
		prefab_name = "",
		content = "带头的军士大声催促，一边拔出插在导流罩内侧的手枪，朝那些荒兽举枪射击。",
