	},
	[323502010] = {
		speaker = "边军军士甲",
		prefab_name = "10162ui_story",
		content = "感谢两位上仙相助。但现在所有城关都下了封锁令，就算是上仙，没有准许也不能出关。",
		id = 323502010
	},
	[323502011] = {
