	},
	[323502013] = {
		speaker = "边军军士甲",
		prefab_name = "10162ui_story",
		content = "两位上仙在山里可能不知道，三天前，杜仲将军带领大军北上了。守备空虚，所有城关自然不让外出。",
		id = 323502013
	},
	[323502014] = {
		speaker = "边军军士甲",
		prefab_name = "10162ui_story",
		content = "秋丹关丞是剑门关的二把手。泰逢关令跟杜仲将军一起北征去了，秋丹关丞便是剑门关最大的官儿。",
		id = 323502014
	},
	[323502015] = {
		speaker = "边军军士甲",
		prefab_name = "10162ui_story",
		content = "往常大荒里有上仙出山，都是杜仲将军或者泰逢关令接待，可不巧他们都不在，那往下数就是找秋丹关丞了。",
		id = 323502015
	},
	[323502016] = {
		speaker = "我",
		prefab_name = "",
		content = "（所以「上仙」指的是修正者吗？大荒里还有修正者觉醒？）",
		id = 323502016
	},
	[323502017] = {
		speaker = "",
		prefab_name = "",
		content = "我半蒙半猜地听着。这三句话里，只有「泰逢」这个名字因为听长琴说过还有印象。其余的人名官名，还有北征之类的词汇，则完全没有概念。",
		id = 323502017
	},
	[323502018] = {
		speaker = "",
		prefab_name = "",
		content = "但我深知现在不能暴露自己信息的缺失，相反，哪怕强装也要先融入，毕竟到了人生地不熟的地方，最忌讳的就是招惹嫌疑。",
		id = 323502018
	},
	[323502019] = {
