	},
	[323502037] = {
		speaker = "",
		prefab_name = "",
		content = "我不好打断他，只能看着他在没找到开关和锁口后开始强掰，越来越使劲，脸色涨得越来越红，剑匣愣是一动不动。",
		id = 323502037
	},
	[323502038] = {
