	},
	[323511016] = {
		speaker = "我",
		prefab_name = "",
		content = "（那咋说嘛，我也不知道啊。）",
		id = 323511016
	},
	[323511017] = {
		speaker = "",
		prefab_name = "",
		content = "望舒看我的眼神像是在诘问江湖骗子，我只能无奈地冲她咧了咧嘴。",
		id = 323511017
	},
	[323511018] = {
		speaker = "",
		prefab_name = "",
		content = "一行人穿过城门，来到关内。这座雄关从内到外俨然完全军事化，经年累月的翻新加固完全遮住了战火风霜曾留下的痕迹。",
		id = 323511018
	},
	[323511019] = {
		speaker = "",
		prefab_name = "",
		content = "临近城楼就是一座规模不小的校场，现在时间未到中午，不少士兵做着午饭前最后的操练。只有一人站在校场边无所事事，垂手望着城门的方向。",
		id = 323511019
	},
	[323511020] = {
