	[323572019] = {
		speaker = "我",
		prefab_name = "",
		content = "总之现在见上面了就好……武罗，我们要去北边看看北征大军的情况，你对大荒更熟悉，能带我们过去吗？",
		id = 323572019
	},
	[323572020] = {
		speaker = "武罗",
		prefab_name = "",
		content = "这不行。秋丹关丞跟你们说过封锁令吧？",
		id = 323572020
	},
	[323572021] = {
		speaker = "我",
		prefab_name = "",
		content = "我们都已经出城了，还在乎那个？",
		id = 323572021
	},
	[323572022] = {
		speaker = "武罗",
		prefab_name = "",
		content = "这不一样。山里没人，只要来回路上不被发现就没事。",
		id = 323572022
	},
	[323572023] = {
		speaker = "武罗",
		prefab_name = "",
		content = "可你们要去找杜仲将军，难免要与北边的关隘接触。要是被边军发现你们偷偷溜出剑门关，秋丹关丞也得跟着挨处分。",
		id = 323572023
	},
	[323572024] = {
		speaker = "武罗",
		prefab_name = "",
		content = "大荒之中军法如山，没有通融的机会，你们可不能把秋丹关丞给害了。",
		id = 323572024
	},
	[323572025] = {
		speaker = "我",
		prefab_name = "",
		content = "那也不能就这么回燕沂城吧？我和望舒都等了一周了，虚恒那边还在等我们的消息。",
		id = 323572025
	},
	[323572026] = {
		speaker = "武罗",
		prefab_name = "",
		content = "我能理解你们很着急，可你们去北边又能有什么发现呢？",
		id = 323572026
	},
	[323572027] = {
		speaker = "武罗",
		prefab_name = "",
		content = "泰泽通讯不畅，消息传回来慢一点也能理解，万一真出了什么变故，五关之间也会通过烽火示警。",
		id = 323572027
	},
	[323572028] = {
		speaker = "武罗",
		prefab_name = "",
		content = "现在什么消息都还没接到，你们是不是担心过头了？",
		id = 323572028
	},
	[323572029] = {
		speaker = "我",
		prefab_name = "",
		content = "……那至少去看看北边的关隘有没有问题。剑门关北边，是碧饶关吧？",
		id = 323572029
	},
	[323572030] = {
		speaker = "武罗",
		prefab_name = "",
		content = "碧饶关能出什么问题……想看就看吧，翻过前面那座山头就能见到了。",
		id = 323572030
	},
	[323572031] = {
		speaker = "",
		prefab_name = "",
		content = "武罗指了个方向，我也没拖延，径直朝那边走去。望舒吃着不知从哪里采过来的树莓，跟在我后面。武罗犹豫了一下，也跟了过来。",
		id = 323572031
	},
	[323572032] = {
		speaker = "",
		prefab_name = "",
		content = "果然，就如武罗所说，翻过山头，远远便能望到又一座雄关横在北方。",
		id = 323572032
	},
	[323572033] = {
		speaker = "",
		prefab_name = "",
		content = "我将望远镜倍率调到最高，仔细观察了一圈，城关上的城防设施、岗哨人员全都齐整，看起来确实没有什么问题。",
		id = 323572033
	},
	[323572034] = {
		speaker = "武罗",
		prefab_name = "",
		content = "所以，是不是可以回去了？",
		id = 323572034
	},
	[323572035] = {
		speaker = "我",
		prefab_name = "",
		content = "……我还是觉得不对劲。",
		id = 323572035
	},
	[323572036] = {
		speaker = "武罗",
		prefab_name = "",
		content = "你还想怎么样嘛……",
		id = 323572036
	},
	[323572037] = {
		speaker = "我",
		prefab_name = "",
		content = "不是我危言耸听，武罗。我和科尔盖接触不浅，知道他们的行事作风。",
		id = 323572037
	},
	[323572038] = {
		speaker = "我",
		prefab_name = "",
		content = "科尔盖最重视情报，该知情的要知情，不该知情的要保密。普通的行政事务都不会出现纰漏，何况是战报？",
		id = 323572038
	},
	[323572039] = {
		speaker = "我",
		prefab_name = "",
		content = "我见过的所有科尔盖参与的行动，全都是前线情况第一时间同步给后方，只要出现延误，就要说明延误的原因。",
		id = 323572039
	},
	[323572040] = {
		speaker = "我",
		prefab_name = "",
		content = "杜仲将军是科尔盖出身，肯定是保有这种习惯的，就算泰泽通讯不便，哪有这么多天没音信的道理？",
		id = 323572040
	},
	[323572041] = {
		speaker = "武罗",
		prefab_name = "",
		content = "你这样怀疑是不是太没凭没据了？",
		id = 323572041
	},
	[323572042] = {
		speaker = "我",
		prefab_name = "",
		content = "不是没凭没据，是我们要考虑所有可能。荒兽这种东西，一刻没有扼杀，那就是放任。",
		id = 323572042
	},
	[323572043] = {
		speaker = "我",
		prefab_name = "",
		content = "虚恒去年刚遭过一次大灾，庚辰不在了，现在经不起动荡。我们得帮她……也是为大荒，守住虚恒。",
		id = 323572043
	},
	[323572044] = {
		speaker = "",
		prefab_name = "",
		content = "武罗没有反驳，只是默默看着我，像是确认了我坚决的态度， 最后默默叹了口气。",
		id = 323572044
	},
	[323572045] = {
		speaker = "武罗",
		prefab_name = "",
		content = "现在只有军务原因才能出剑门关。",
		id = 323572045
	},
	[323572046] = {
		speaker = "我",
		prefab_name = "",
		content = "……你不会想让我们参军吧？",
		id = 323572046
	},
	[323572047] = {
		speaker = "武罗",
		prefab_name = "",
		content = "不是……你们现在参军也只会被安排守城。",
		id = 323572047
	},
	[323572048] = {
		speaker = "武罗",
		prefab_name = "",
		content = "我和边军还算有些合作，你们非要北上的话，我想想办法吧。",
		id = 323572048
	},
	[323581001] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "「新型履带」？",
		id = 323581001
	},
	[323581002] = {
		speaker = "武罗",
		prefab_name = "",
		content = "是的，我研究了一下之前从泰泽采回来的黑砂样本。如果这种黑砂堆积过厚，部队现在的地面载具还是容易陷进去。",
		id = 323581002
	},
	[323581003] = {
		speaker = "",
		prefab_name = "",
		content = "剑门关的行政区离守军的营区有些距离，还算僻静，秋丹的办公室内不用当心隔墙有耳，我们说话也就不必有太多顾虑。",
		id = 323581003
	},
	[323581004] = {
		speaker = "",
		prefab_name = "",
		content = "但此时屋内的氛围并不如想象中和谐。秋丹看着一本正经的武罗，又斜过身子，看了看她身后同样一本正经的我和望舒，眼神中的困惑慢慢转变为怀疑。",
		id = 323581004
	},
	[323581005] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "你要去北边。他们呢？",
		id = 323581005
	},
	[323581006] = {
		speaker = "武罗",
		prefab_name = "",
		content = "北边在打仗，情况不明，我找他们护送我。",
		id = 323581006
	},
	[323581007] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "……武罗上仙啊，咱们官道一路通到雁门关，畅通无阻，您又是修正者，何来护送一说啊？",
		id = 323581007
	},
	[323581008] = {
		speaker = "武罗",
		prefab_name = "",
		content = "你知不知道这位前辈是谁？",
		id = 323581008
	},
	[323581009] = {
		speaker = "",
		prefab_name = "",
		content = "武罗回头看了眼望舒。秋丹不明所以。望舒没什么反应。我吓了一跳，担心武罗说出什么招风的话，连忙上前一步打圆场。",
		id = 323581009
	},
	[323581010] = {
		speaker = "我",
		prefab_name = "",
		content = "望舒认识武罗的老师。我们来大荒之前，她老师嘱咐我们，有事可以找武罗，多互帮互助。",
		id = 323581010
	},
	[323581011] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "是……是这样吗？",
		id = 323581011
	},
	[323581012] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "是有这么回事。",
		id = 323581012
	},
	[323581013] = {
		speaker = "武罗",
		prefab_name = "",
		content = "……是有这么回事。",
		id = 323581013
	},
	[323581014] = {
		speaker = "",
		prefab_name = "",
		content = "武罗大概也明白了我的意思，看我不像是在扯谎，便顺着我们的话往下说。我注意到她的视线，大大方方地冲她笑了笑了，做出一副都是熟人的模样。",
		id = 323581014
	},
	[323581015] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "既然是长琴上仙的意思，又是熟人，同行倒也合情理。",
		id = 323581015
	},
	[323581016] = {
		speaker = "武罗",
		prefab_name = "",
		content = "那通关文牒——",
		id = 323581016
	},
	[323581017] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "审批通关文牒要材料齐备，不能你说两句话，我就放行了。既然是有新的设计，那得把设计图拿出来。",
		id = 323581017
	},
	[323581018] = {
		speaker = "我",
		prefab_name = "",
		content = "（坏了。临时编的理由，哪儿来的设计图？）",
		id = 323581018
	},
	[323581019] = {
		speaker = "",
		prefab_name = "",
		content = "这下连我也不知道该怎么圆了，只能忐忑地看向武罗，却发现她面无波澜，从怀里掏出一块微型数据盘，递给秋丹。",
		id = 323581019
	},
	[323581020] = {
		speaker = "武罗",
		prefab_name = "",
		content = "履带的设计图，还有现在几款主流载具的更换方案，都在里面。",
		id = 323581020
	},
	[323581021] = {
		speaker = "我",
		prefab_name = "",
		content = "（你真有啊？！）",
		id = 323581021
	},
	[323581022] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "好的……可既然有这样的东西，为什么大军北征之前没听你提起？",
		id = 323581022
	},
	[323581023] = {
		speaker = "武罗",
		prefab_name = "",
		content = "北征之前还有别的工作啊。而且当时方案只有个雏形，杜仲将军怎么可能为了等我把方案做完延后出发的时间？",
		id = 323581023
	},
	[323581024] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "这倒也是，筹备工作又多又杂，出发的时间已经是一拖再拖了。",
		id = 323581024
	},
	[323581025] = {
		speaker = "武罗",
		prefab_name = "",
		content = "那通关文牒——",
		id = 323581025
	},
	[323581026] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "我不懂技术，这方案我得拿给技术官看看。快则一天慢则两天吧。",
		id = 323581026
	},
	[323581027] = {
		speaker = "我",
		prefab_name = "",
		content = "能不能加急处理一下？我们时间挺紧的。",
		id = 323581027
	},
	[323581028] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "加急也没用。要出关，这关内的事得办完吧。",
		id = 323581028
	},
	[323581029] = {
		speaker = "",
		prefab_name = "",
		content = "秋丹将那块数据盘收好，坐回到椅子上，用一种像是提醒的眼神看着武罗。武罗愣了好一会儿，才苦恼地揉了揉额头。",
		id = 323581029
	},
	[323581030] = {
		speaker = "我",
		prefab_name = "",
		content = "怎么了，武罗？",
		id = 323581030
	},
	[323581031] = {
		speaker = "武罗",
		prefab_name = "",
		content = "就是这些。",
		id = 323581031
	},
	[323581032] = {
		speaker = "",
		prefab_name = "",
		content = "「武罗机电」深处的卷帘门升到顶，里间是个比铺面整洁不少的工作间。工作间中央的空地上放着两台胸部以上还没组装好的自动机甲，武罗指的显然就是它们。",
		id = 323581032
	},
	[323581033] = {
		speaker = "武罗",
		prefab_name = "",
		content = "我没参加北征，不过答应杜仲将军要留在后方巩固城防。应该做完的东西还没交付，所以……",
		id = 323581033
	},
	[323581034] = {
		speaker = "我",
		prefab_name = "",
		content = "那几个瞬态脉冲器是新加的吧？现在在调动平衡？",
		id = 323581034
	},
	[323581035] = {
		speaker = "",
		prefab_name = "",
		content = "武罗诧异地看着我，手套在手指边蹭了好几下都没戴上去。注意到自己的失态，她忙不迭低头把手套戴好，却还是有些不可思议地轻笑一声，摇了摇头。",
		id = 323581035
	},
	[323581036] = {
		speaker = "武罗",
		prefab_name = "",
		content = "你也是搞机械的？",
		id = 323581036
	},
	[323581037] = {
		speaker = "我",
		prefab_name = "",
		content = "听说……失忆以前是，现在只是略懂。",
		id = 323581037
	},
	[323581038] = {
		speaker = "武罗",
		prefab_name = "",
		content = "略懂的水平，一眼可看不出这些。",
		id = 323581038
	},
	[323581039] = {
		speaker = "我",
		prefab_name = "",
		content = "巧合而已，我见过科尔盖这个型号机甲的最新款。",
		id = 323581039
	},
	[323581040] = {
		speaker = "",
		prefab_name = "",
		content = "这两台智械胸部以上还没组装，估摸全高有四米左右，算是类人形的自动机甲，我百分百确定自己在科尔盖见过类似的东西。",
		id = 323581040
	},
	[323581041] = {
		speaker = "",
		prefab_name = "",
		content = "我绕到那两台智械的另一侧，俯身去找原本应该印在它们侧后方的、印有科尔盖标志的铭牌，但那里空空如也。",
		id = 323581041
	},
	[323581042] = {
		speaker = "武罗",
		prefab_name = "",
		content = "铭牌的话，被我挪到后颈的位置了，脑袋还没装上去。",
		id = 323581042
	},
	[323581043] = {
		speaker = "",
		prefab_name = "",
		content = "既然是「还没装上去」的部件，那必然就在附近，我环视工作间，果然看到两块规格匹配的头颈部件。只是……",
		id = 323581043
	},
	[323581044] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "……对了，如果你们遇到她，在她面前……要注意尊重一下她的个人爱好。",
		id = 323581044
	},
	[323581045] = {
		speaker = "我",
		prefab_name = "",
		content = "……头部的造型，挺别致啊。",
		id = 323581045
	},
	[323581046] = {
		speaker = "武罗",
		prefab_name = "",
		content = "是吧！我就觉得这么可爱一定会有人喜欢的！",
		id = 323581046
	},
	[323581047] = {
		speaker = "",
		prefab_name = "",
		content = "见我注意到那两个机器熊猫头，武罗忽然来了兴致，跑过去将它们抱到桌上，像是这样能让我借着灯光看得更清楚一点。",
		id = 323581047
	},
	[323581048] = {
		speaker = "武罗",
		prefab_name = "",
		content = "可秋丹又说「和原造型差异过大」，让我改回去，唉……",
		id = 323581048
	},
	[323581049] = {
		speaker = "我",
		prefab_name = "",
		content = "你也知道科尔盖，或者说现在的边军，都是比较……呃，硬派的审美。应该能想到他们会拒绝这种风格吧？",
		id = 323581049
	},
	[323581050] = {
		speaker = "武罗",
		prefab_name = "",
		content = "我知道军队需要保持严肃性，令行禁止什么的。",
		id = 323581050
	},
	[323581051] = {
		speaker = "武罗",
		prefab_name = "",
		content = "可战争都已经那么无情了，陪在士兵身边的机器还非要做成冷冰冰的样子吗？",
		id = 323581051
	},
	[323581052] = {
		speaker = "",
		prefab_name = "",
		content = "好像对于「说服我」这件事没什么信心也没什么兴致，武罗的声音很快小了下去，她用力按着手里的机器熊猫头，好像希望能快点跳过这个话题。",
		id = 323581052
	},
	[323581053] = {
		speaker = "武罗",
		prefab_name = "",
		content = "……是我喜欢熊猫没错，我也只是希望能把热情分享出去。",
		id = 323581053
	},
	[323581054] = {
		speaker = "我",
		prefab_name = "",
		content = "应该只是外观上有更改吧，功能没影响？",
		id = 323581054
	},
	[323581055] = {
		speaker = "武罗",
		prefab_name = "",
		content = "没有。",
		id = 323581055
	},
	[323581056] = {
		speaker = "我",
		prefab_name = "",
		content = "那可不行啊。",
		id = 323581056
	},
	[323581057] = {
		speaker = "",
		prefab_name = "",
		content = "武罗有些茫然地看着我。我走到她旁边，学着她的动作，按住桌上的另一个机器熊猫头。",
		id = 323581057
	},
	[323581058] = {
		speaker = "我",
		prefab_name = "",
		content = "什么商务谈判啊、方案研讨啊，我参加得都比较多。作为乙方呢，想说服甲方额外接受什么东西，颠扑不破的道理，就是让对方感受到「这东西是真有用」。",
		id = 323581058
	},
	[323581059] = {
		speaker = "武罗",
		prefab_name = "",
		content = "你是说……",
		id = 323581059
	},
	[323581060] = {
		speaker = "我",
		prefab_name = "",
		content = "再出一套新的方案吧，我和望舒也来帮忙。",
		id = 323581060
	},
	[323581061] = {
		speaker = "",
		prefab_name = "",
		content = "听到我喊她的名字，望舒扭头看了我一眼，然后接着低头摆弄起工作间墙角的盆栽。我只能尴尬地笑笑，当作望舒的反应是默认同意了。",
		id = 323581061
	},
	[323581062] = {
		speaker = "武罗",
		prefab_name = "",
		content = "不是我怀疑你们的水平……了解是一回事，改装又是另一回事了。",
		id = 323581062
	},
	[323581063] = {
		speaker = "我",
		prefab_name = "",
		content = "提供一些参考建议应该还是可以的。可别忘了，在大荒外面，科尔盖可是有一整支技术团队年复一年地研究这些武器装备的改进。",
		id = 323581063
	},
	[323581064] = {
		speaker = "我",
		prefab_name = "",
		content = "虽然两边的应用情景不一样，技术发展路径也不一样，但总有可以取长补短的地方……",
		id = 323581064
	},
	[323581065] = {
		speaker = "",
		prefab_name = "",
		content = "虽然这么做的象征意义更多一些，我拿起一把桌上的羊角锤，在手里掂了掂。",
		id = 323581065
	},
	[323581066] = {
		speaker = "我",
		prefab_name = "",
		content = "证明给秋丹看吧，熊猫机甲不止是可爱而已。",
