	},
	[323591001] = {
		speaker = "武罗",
		prefab_name = "",
		content = "紧了紧了！",
		id = 323591001
	},
	[323591002] = {
		speaker = "",
		prefab_name = "",
		content = "武罗踩在人字梯上，半颗脑袋埋在智械躯干里面。我看不到智械里的状况，只能按照她的指示，在数控屏幕上把气阀的压力往下拨了两格。",
		id = 323591002
	},
	[323591003] = {
		speaker = "武罗",
		prefab_name = "",
		content = "唔……松了松了！",
		id = 323591003
	},
	[323591004] = {
		speaker = "我",
		prefab_name = "",
		content = "我才调了2%啊。",
		id = 323591004
	},
	[323591005] = {
		speaker = "武罗",
		prefab_name = "",
		content = "再拨回去一点！",
		id = 323591005
	},
	[323591006] = {
		speaker = "",
		prefab_name = "",
		content = "我只好又往回拨了一格。武罗没了动静，过了好一会儿，她摸过挂在腰带上的锤子，伸到里面叮叮当当敲了几下，然后猛然抬起头。",
		id = 323591006
	},
	[323591007] = {
		speaker = "武罗",
		prefab_name = "",
		content = "头！",
		id = 323591007
	},
	[323591008] = {
		speaker = "",
		prefab_name = "",
		content = "站在武罗旁边的望舒把抱在怀里的机器熊猫头递给她。在武罗处理头部的卡榫和插槽时，望舒将智械背后的几处气密口逐一盖上。",
		id = 323591008
	},
	[323591009] = {
		speaker = "",
		prefab_name = "",
		content = "等武罗朝我比起大拇指，我启动了智械的自检程序。当闪烁的黄色信号灯跳成长亮的绿色，武罗终于松了口气，从梯子上爬下来，擦去额前的汗珠，冲我们笑了笑。",
		id = 323591009
	},
	[323591010] = {
