	[323591015] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "……知道就是知道。",
		id = 323591015
	},
	[323591016] = {
		speaker = "",
		prefab_name = "",
		content = "我条件反射般地举手投降，根据这几天和她相处的经验，听到这句话以后就可以放弃追问了。",
		id = 323591016
	},
	[323591017] = {
		speaker = "",
		prefab_name = "",
		content = "与武罗一起忙里忙外改了两天智械，我们之间慢慢没了生疏的感觉，在她的工作间里歇息也是常事，我都感觉我拖来一只马扎坐下的动作过于娴熟了。",
		id = 323591017
	},
	[323591018] = {
		speaker = "我",
		prefab_name = "",
		content = "这两天可真是……好好体验了一把机械师的工作。",
		id = 323591018
	},
	[323591019] = {
		speaker = "武罗",
		prefab_name = "",
		content = "我现在相信了，你以前绝对干过这行。",
		id = 323591019
	},
	[323591020] = {
		speaker = "我",
		prefab_name = "",
		content = "难说，大家都说我学什么都快。倒是我比较意外，没想到你这么擅长这一行。",
		id = 323591020
	},
	[323591021] = {
		speaker = "武罗",
		prefab_name = "",
		content = "是吗？为什么？",
		id = 323591021
	},
	[323591022] = {
		speaker = "我",
		prefab_name = "",
		content = "先入为主的印象吧……来大荒之前我听说你是铸剑术的传人，以为手艺会更加复古一点。",
		id = 323591022
	},
	[323591023] = {
		speaker = "武罗",
		prefab_name = "",
		content = "大荒需要的是军队，不是江湖剑客。我留在大荒也是为了帮助边军，铸剑术暂时就放一放了。",
		id = 323591023
	},
	[323591024] = {
		speaker = "",
		prefab_name = "",
		content = "武罗从冰箱里拿出三瓶功能饮料，先后递给我和望舒一瓶。碰上望舒审视的目光时，她微微偏过头，转身朝我这边靠了靠。",
		id = 323591024
	},
	[323591025] = {
		speaker = "我",
		prefab_name = "",
		content = "好吧……这是一方面。另一方面是，没想到你这么难找。",
		id = 323591025
