	[323611029] = {
		speaker = "我",
		prefab_name = "",
		content = "当归？你街对面的邻居？",
		id = 323611029
	},
	[323611030] = {
		speaker = "",
		prefab_name = "",
		content = "正在我不远处检修城防炮的武罗把扳手递给身边的技工，愣愣地望着战场东边那道朝剑门关飞奔过来的身影。",
		id = 323611030
	},
	[323611031] = {
		speaker = "武罗",
		prefab_name = "",
		content = "是，我邻居……也是杜仲将军的传令官。",
		id = 323611031
	},
	[323611032] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "传将军令……咳咳……传将军令！",
		id = 323611032
	},
	[323611033] = {
		speaker = "我",
		prefab_name = "",
		content = "快！去救人！",
		id = 323611033
	},
	[323612001] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "咕——咕——",
		id = 323612001
	},
	[323612002] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "慢点，别喝太急……",
		id = 323612002
	},
	[323612003] = {
		speaker = "",
		prefab_name = "",
		content = "这位叫当归的小伙子显然是累坏了，口干舌燥，声音嘶哑，几乎是被士兵们抬回剑门关。",
		id = 323612003
	},
	[323612004] = {
		speaker = "",
		prefab_name = "",
		content = "军医给他吃了点补气润喉的药。他就着水吃了几口干粮，低着头，脸上泪水混着汗珠。秋丹拿了块毛巾给他擦了擦，他又坐了几分钟，总算缓了过来。",
		id = 323612004
	},
	[323612005] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "秋丹关丞……",
		id = 323612005
	},
	[323612006] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "出什么事了？大军怎么样了？",
		id = 323612006
	},
	[323612007] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "暂时没事，在雁门关。",
		id = 323612007
	},
	[323612008] = {
		speaker = "",
		prefab_name = "",
		content = "武罗松了口气，秋丹却皱起了眉。当归揉了揉嗓子，继续往下说。",
		id = 323612008
	},
	[323612009] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "我们在泰泽被袭击了。整片土地，那些黑色的砂石全部都在动……说不清发生了什么，然后就是荒兽……",
		id = 323612009
	},
	[323612010] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "好在杜仲将军提前留了退路，加上后土上仙的神通，主力撤回了雁门关。",
		id = 323612010
	},
	[323612011] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "原本想在雁门关休整一下，结果南北两边不知什么时候全被荒兽包围了，通讯全断，无路可走。",
		id = 323612011
	},
	[323612012] = {
		speaker = "武罗",
		prefab_name = "",
		content = "荒兽真会围城？有四凶在指挥吗？",
		id = 323612012
	},
	[323612013] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "四凶……不，不是……",
		id = 323612013
	},
	[323612014] = {
		speaker = "",
		prefab_name = "",
		content = "说到这里，当归喉头蠕动了一下，眼中露出一丝恐惧，意识到自己失语，才勉强将它压了下去。",
		id = 323612014
	},
	[323612015] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "是一个人。我们不知道他是什么东西，反正就是人的样貌。是他在指挥荒兽。",
		id = 323612015
	},
	[323612016] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "泰逢关令想着擒贼先擒王，可不到十招就败了，幸好有后土上仙援救……她还在雁门关养伤，所以这几天都没能突围。",
		id = 323612016
	},
	[323612017] = {
		speaker = "我",
		prefab_name = "",
		content = "是不是叫相柳？",
		id = 323612017
	},
	[323612018] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "不知道名字，是个老人，白须白发，穿一身锦袍。",
		id = 323612018
	},
	[323612019] = {
		speaker = "我",
		prefab_name = "",
		content = "……不是相柳？难道和智骸一样，还有同类吗？",
		id = 323612019
	},
	[323612020] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "智骸？是什么？",
		id = 323612020
	},
	[323612021] = {
		speaker = "我",
		prefab_name = "",
		content = "你是真的两耳不闻窗外事啊。有空再解释吧……",
		id = 323612021
	},
	[323612022] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "既然雁门关被围，你一个人是怎么到这里来的？",
		id = 323612022
	},
	[323612023] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "不是我一个人，还有我师父。",
		id = 323612023
	},
	[323612024] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "定远老哥？那他……",
		id = 323612024
	},
	[323612025] = {
		speaker = "",
		prefab_name = "",
		content = "当归不说话了，摇摇头，双目一阵阵地无神，到最后只能苦笑。",
		id = 323612025
	},
	[323612026] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "杜仲将军知道前线太久没消息，后方一定会骚乱，所以和后土上仙琢磨了个声东击西的法子，掩护我和师父出关。",
		id = 323612026
	},
	[323612027] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "我们一路南下，发现还有一支荒兽潮南下，碣石、乾伦、碧饶三关全毁了。不知道死了多少人……",
		id = 323612027
	},
	[323612028] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "到了碧饶关，我们发现剑门关被围，通讯被荒兽潮散发出的能量干扰，联系不上你们。如果硬闯，我和师父肯定闯不过来。",
		id = 323612028
	},
	[323612029] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "所以师父……师父就留在碧饶关，敲钟，敲钟，一直敲，直到附近的荒兽全被吸引过去，我贴着东边荒兽最少的地方，一直跑……",
		id = 323612029
	},
	[323612030] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "……定远老哥在战场上摸爬滚打了不知多少年，经验丰富，未必有事。稍晚我派一架运输机，去碧饶关找他。",
		id = 323612030
	},
	[323612031] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "不，不……",
		id = 323612031
	},
	[323612032] = {
		speaker = "",
		prefab_name = "",
		content = "当归有些恍神，好像对接下来要说的话生出了犹豫，但最后还是长叹一声，从背后抽出一支令旗，递给秋丹。",
		id = 323612032
	},
	[323612033] = {
		speaker = "秋丹",
		prefab_name = "10164ui_story",
		content = "……见旗如见人，秋丹听令。",
		id = 323612033
	},
	[323612034] = {
		speaker = "当归",
		prefab_name = "10165ui_story",
		content = "杜仲将军有令：荒兽势大，后方空虚。只可固守，不可北出。",
		id = 323612034
	},
	[323621001] = {
		speaker = "我",
		prefab_name = "",
		content = "……回去吧。",
		id = 323621001
	},
	[323621002] = {
		speaker = "",
		prefab_name = "",
		content = "沉思许久，我抬头看向望舒，轻轻叹了口气。安顿好当归后，秋丹和武罗回到了前线，后方的客房里只有我和望舒两人。",
		id = 323621002
	},
	[323621003] = {
		speaker = "",
		prefab_name = "",
		content = "我坐着，她站着。她剥着从行云客栈带过来的橘子，神色平常，与那晚在四方院客房里第一次找到我时没什么变化。",
		id = 323621003
	},
	[323621004] = {
		speaker = "我",
		prefab_name = "",
		content = "荒兽能在雁门关困住北征大军，同时还能分出力量来围攻剑门关，可以说大荒现有的力量已经不足以解决这里的麻烦了。",
		id = 323621004
	},
	[323621005] = {
		speaker = "我",
		prefab_name = "",
		content = "这必然不是常态，否则大荒不可能撑到现在。也有理由相信，相柳的出现和大荒局面的变化有关系……",
		id = 323621005
	},
	[323621006] = {
		speaker = "我",
		prefab_name = "",
		content = "所以，比起在这里多守几天，把消息带回去，共同商讨对策，才是援救大荒最好的办法。",
		id = 323621006
	},
	[323621007] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "其他人过不来，进太虚死路一条。",
		id = 323621007
	},
	[323621008] = {
		speaker = "我",
		prefab_name = "",
		content = "真有这么恐怖吗……办法都是人想出来的。",
		id = 323621008
	},
	[323621009] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "一来一回又要十天，太久了。",
		id = 323621009
	},
	[323621010] = {
		speaker = "我",
		prefab_name = "",
		content = "我知道这很冒险，但现在也只能相信秋丹他们……",
		id = 323621010
	},
	[323621011] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "我留下，你回去。",
		id = 323621011
	},
	[323621012] = {
		speaker = "我",
		prefab_name = "",
		content = "什么？",
		id = 323621012
	},
	[323621013] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "北边还有荒兽过来。我不在，他们守不住。",
		id = 323621013
	},
	[323621014] = {
		speaker = "我",
		prefab_name = "",
		content = "可你一个人在这里……",
		id = 323621014
	},
	[323621015] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "我一个人在这里？",
		id = 323621015
	},
	[323621016] = {
		speaker = "我",
		prefab_name = "",
		content = "……没关系吗？",
		id = 323621016
	},
	[323621017] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "我在瑶池苏醒的时候，就是一个人。",
		id = 323621017
	},
	[323621018] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "诺尔薇在瑶池住过两个月，和你来大荒两周，和长琴见过两次面。其余时间，都是一个人。没关系。",
		id = 323621018
	},
	[323621019] = {
		speaker = "",
		prefab_name = "",
		content = "我张了张嘴，不知道该说什么。数十年孑然一身，放在任何人身上都是一种煎熬，但望舒又不能以常理度之，看得出来她是真的不在乎……",
		id = 323621019
	},
	[323621020] = {
		speaker = "我",
		prefab_name = "",
		content = "……是真的不在乎吗？",
		id = 323621020
	},
	[323621021] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "？",
		id = 323621021
	},
	[323621022] = {
		speaker = "我",
		prefab_name = "",
		content = "不……没什么。\n问题是我一个人也回不去啊，你说过在太虚里会走丢。",
		id = 323621022
	},
	[323621023] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "……你还没明白。",
		id = 323621023
	},
	[323621024] = {
		speaker = "",
		prefab_name = "",
		content = "在我茫然的注视下，望舒拎起我放在床头的剑匣，塞到我怀里，然后拿起倚在墙边的玄问。",
		id = 323621024
	},
	[323621025] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "带着承钧。有神剑护持，知觉就不会偏移。",
		id = 323621025
	},
	[323621026] = {
		speaker = "我",
		prefab_name = "",
		content = "怎么个护持法？我就背着？",
		id = 323621026
	},
	[323621027] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "对，就背着，只需要往前走就好了。剩下的交给我。",
		id = 323621027
	},
	[323621028] = {
		speaker = "",
		prefab_name = "",
		content = "她想了想，又丢给我一块令牌，中央有着一个与瑶池操作台屏幕左上角同样的标志，似乎还是个按键。",
		id = 323621028
	},
	[323621029] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "十天以后，还是这个时间，我再开一条通道，入口还在长琴那里。",
		id = 323621029
	},
	[323621030] = {
		speaker = "我",
		prefab_name = "",
		content = "好吧，总之我早点过去等你，只要你打开通道，我马上过来……不过这个是什么？",
		id = 323621030
	},
	[323621031] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "瑶池的钥匙。到昆仑，按一下，就进去了。",
		id = 323621031
	},
	[323621032] = {
		speaker = "我",
		prefab_name = "",
		content = "……你给我这个干什么？",
		id = 323621032
	},
	[323621033] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "你是诺尔薇的弟弟。如果我没办法接你，瑶池要还给你。",
		id = 323621033
	},
	[323621034] = {
		speaker = "",
		prefab_name = "",
		content = "熟悉的挽剑手法，熟悉的空间裂缝，望舒看上去毫不费力，但玄问散发的华光一瞬间似乎弱了许多。",
		id = 323621034
	},
	[323621035] = {
		speaker = "",
		prefab_name = "",
		content = "我还没来得及细看，望舒将我从床上拉起来，就要把我丢到那空间裂缝里，我连忙拉住她的手，没让她继续使劲。",
		id = 323621035
	},
	[323621036] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "怎么了？",
		id = 323621036
	},
	[323621037] = {
		speaker = "我",
		prefab_name = "",
		content = "我不想听你说这些。",
		id = 323621037
	},
	[323621038] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "说什么？",
		id = 323621038
	},
	[323621039] = {
		speaker = "我",
		prefab_name = "",
		content = "「没办法接我」什么的……",
		id = 323621039
	},
	[323621040] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "世事难料，总会有个「万一」。如果我没事，会准时打开通道。但如果我——",
		id = 323621040
	},
	[323621041] = {
		speaker = "我",
		prefab_name = "",
		content = "停，够了……我说了我不想听。",
		id = 323621041
	},
	[323621042] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "……果然是弟弟，还像小孩一样。",
		id = 323621042
	},
	[323621043] = {
		speaker = "我",
		prefab_name = "",
		content = "到底是谁不让人放心啊……",
		id = 323621043
	},
	[323621044] = {
		speaker = "",
		prefab_name = "",
		content = "慢慢松开望舒的手，我五味杂陈地笑了笑，伸手为她整理好在战斗中稍有些皱起的衣领。",
		id = 323621044
	},
	[323621045] = {
		speaker = "我",
		prefab_name = "",
		content = "保护好剑门关，也保护好自己。",
		id = 323621045
	},
	[323621046] = {
		speaker = "",
		prefab_name = "",
		content = "望舒依然没说话，只是按住我的胸口。熟悉的动作。我知道她要做什么，只是这回已经做好准备了。",
		id = 323621046
	},
	[323621047] = {
		speaker = "我",
		prefab_name = "",
		content = "……等我回来。",
		id = 323621047
	},
	[323621048] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "……",
		id = 323621048
	},
	[323621049] = {
		speaker = "",
		prefab_name = "",
		content = "按在我胸口的手掌松了一下，而后轻轻一推。汹涌的能量仿佛海上的浪涛，将我卷进又一次旅途。",
		id = 323621049
	},
	[323701001] = {
		speaker = "工头",
		prefab_name = "",
		content = "喂，经理……哎，对，有个小伙儿，说是什么「深空之眼」来考察项目的，保不保真？",
		id = 323701001
	},
	[323701002] = {
		speaker = "工头",
		prefab_name = "",
		content = "……啥？刚和舆昊老板开完会……哦，没有没有，哪儿会随便起冲突，只是让那位小哥先等一会儿……",
		id = 323701002
	},
	[323701003] = {
		speaker = "工头",
		prefab_name = "",
		content = "哎，哎，好，我都知道，不会怠慢，不会怠慢，经理放心……",
		id = 323701003
	},
	[323701004] = {
		speaker = "",
		prefab_name = "",
		content = "我左右观察着工地，努力不去关注这位工头说的话。也许是因为适应了工地的嘈杂，他刻意压低以后的声音在五米远的距离上依然能让我听清。",
		id = 323701004
	},
	[323701005] = {
		speaker = "",
		prefab_name = "",
		content = "直到他关闭通讯，搓着手朝我走过来，我才装作什么都没听见似的，笑脸迎了上去。",
		id = 323701005
	},
	[323701006] = {
		speaker = "我",
		prefab_name = "",
		content = "没问题吧？",
		id = 323701006
	},
	[323701007] = {
		speaker = "工头",
		prefab_name = "",
		content = "没问题，没问题，都核实过了。不过老实说，项目的进度在网上都有公示，小领导您不用专门跑到工地上。",
		id = 323701007
	},
	[323701008] = {
		speaker = "我",
		prefab_name = "",
		content = "什么小领导……我也是公司职员，跟你一样的。",
		id = 323701008
	},
	[323701009] = {
		speaker = "我",
		prefab_name = "",
		content = "我也是刚到虚恒，正好下午没安排，就到处走走。网上有的只有数据、图片、模型。工程是一砖一瓦垒起来的，看得见摸得着才是真的。",
		id = 323701009
	},
	[323701010] = {
		speaker = "工头",
		prefab_name = "",
		content = "嘿！办公室里多几个您这样的人，我们干活儿也踏实。",
		id = 323701010
	},
	[323701011] = {
		speaker = "工头",
		prefab_name = "",
		content = "那我就跟您说说现在工程的情况……",
		id = 323701011
	},
	[323701012] = {
		speaker = "",
		prefab_name = "",
		content = "轩辕计划的城市重建工程从玉京旧址启动，一期工程的目标是重建一个区，涵盖各大用地分类，可以说麻雀虽小五脏俱全。",
		id = 323701012
	},
	[323701013] = {
		speaker = "",
		prefab_name = "",
		content = "和孟章早上在旸山时说的一样，现在一期工程进度平稳，旧的楼房全部推倒，按照新的样式和施工标准重建。",
		id = 323701013
	},
	[323701014] = {
		speaker = "工头",
		prefab_name = "",
		content = "……我们良工集团啊，现在都是模块化施工。老建筑不符合标准，推掉重建还更省事儿呢。",
		id = 323701014
	},
	[323701015] = {
		speaker = "工头",
		prefab_name = "",
		content = "就是清理地基麻烦，不过有些加固改造一下还能用，所以整体没耽搁太多时间。",
		id = 323701015
	},
	[323701016] = {
		speaker = "我",
		prefab_name = "",
		content = "是这样……那边的警戒线是干什么用的，地上应该没别人吧？",
		id = 323701016
	},
	[323701017] = {
		speaker = "工头",
		prefab_name = "",
		content = "哦，那个是四方院拉起来的，说附近有野兽出没，那条警戒线能拦一下。",
		id = 323701017
	},
	[323701018] = {
		speaker = "我",
		prefab_name = "",
		content = "什么野兽，你们见过吗？",
		id = 323701018
	},
	[323701019] = {
		speaker = "工头",
		prefab_name = "",
		content = "没见过，不过您也知道，这些地质水文自然生态什么的，都归四方院管。他们说有，那就是有吧。",
		id = 323701019
	},
	[323701020] = {
		speaker = "工头",
		prefab_name = "",
		content = "哎，正好执明代理也在，您要是对这个感兴趣，要不找她聊聊？",
		id = 323701020
	},
	[323701021] = {
		speaker = "我",
		prefab_name = "",
		content = "啊？执明在这里吗？",
		id = 323701021
	},
	[323701022] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "我不能在这里吗？",
		id = 323701022
	},
	[323701023] = {
		speaker = "我",
		prefab_name = "",
		content = "没有没有，您工作辛苦，哈哈。",
		id = 323701023
	},
	[323701024] = {
		speaker = "",
		prefab_name = "",
		content = "执明白了我一眼，然后把我拉到一幢建筑后面。远处偷偷朝我们这里张望的工人们一阵惋惜地叹气，只好继续忙起手头的活计来。",
		id = 323701024
	},
	[323701025] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "你还知道我是来工作的。那你来干什么？",
		id = 323701025
	},
	[323701026] = {
		speaker = "我",
		prefab_name = "",
		content = "我？我来找你呀。",
		id = 323701026
	},
	[323701027] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "少油腔滑调的……你跟良工集团的会开得怎么样了？",
		id = 323701027
	},
	[323701028] = {
		speaker = "我",
		prefab_name = "",
		content = "没问题，我念稿子，舆昊老板盖章子，一切顺利。",
		id = 323701028
	},
	[323701029] = {
		speaker = "我",
		prefab_name = "",
		content = "所以现在这个轩辕计划，深空之眼也算参与方了，我当然要来看看有没有什么疏漏需要我们帮忙的。",
		id = 323701029
	},
	[323701030] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "工程方面不会有疏漏。稳妥起见，这回调拨给良工集团的各项资源都是超量的。",
		id = 323701030
	},
	[323701031] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "我来这里，是因为视骸。",
		id = 323701031
	},
	[323701032] = {
		speaker = "我",
		prefab_name = "",
		content = "那些警戒线？",
		id = 323701032
	},
	[323701033] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "是，其实是科尔盖的神能隔离带，专门防视骸用的，但对人工神能的消耗也很大。",
		id = 323701033
	},
	[323701034] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "没办法，最近视骸活动又变得频繁，大张旗鼓地派人保护工地又容易起争议，所以只能这样。等一期工程完成，我们和科尔盖入驻以后就好了。",
		id = 323701034
	},
	[323701035] = {
		speaker = "我",
		prefab_name = "",
		content = "视骸的来源有查到吗？",
		id = 323701035
	},
	[323701036] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "不知道，源层还算安稳，可能是图灵那次袭击以后遗落在下界的。",
		id = 323701036
	},
	[323701037] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "正好，我打算去附近看看，你要一起来吗？",
		id = 323701037
	},
	[323701038] = {
		speaker = "我",
		prefab_name = "",
		content = "嘶，你要让一个弱小的人类去调查视骸——哎呦痛痛痛！",
		id = 323701038
	},
	[323701039] = {
		speaker = "",
		prefab_name = "",
		content = "腰侧被执明用力拧了一下，我嬉笑着跳开，却见她转身就走。",
		id = 323701039
	},
	[323701040] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "我先去静督山看看，然后检查一下这里到升降梯之间的交通线。你要来就来吧。",
		id = 323701040
	},
	[323712001] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "果然还有视骸……山区地势复杂，藏污纳垢，视骸真是清理不完。",
		id = 323712001
	},
	[323712002] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "看什么呢？",
		id = 323712002
	},
	[323712003] = {
		speaker = "",
		prefab_name = "",
		content = "纤尘不染的空气，参差交叠的山峦。余光看到执明站到我身边，我转过头看了她一眼，而后继续眺望静督山间的景象。",
		id = 323712003
	},
	[323712004] = {
		speaker = "我",
		prefab_name = "",
		content = "记得去年也是在这儿……好像就是这条路吧。当时其他三位代理都在，我就在想，什么时候有空见一见剩下那位神秘的执明代理呢？",
		id = 323712004
	},
	[323712005] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "……你还有一句正经话吗？",
		id = 323712005
	},
	[323712006] = {
		speaker = "我",
		prefab_name = "",
		content = "冤枉啊，这还不正经吗？我真是这么想的。",
		id = 323712006
	},
	[323712007] = {
		speaker = "我",
		prefab_name = "",
		content = "你说当时要是你在，这山上机关什么的，也不至于被孟章瞎忽悠。",
		id = 323712007
	},
	[323712008] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "他学的那点皮毛，也就在你们这些外行面前卖弄卖弄了。",
		id = 323712008
	},
	[323712009] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "……可惜啊，烛有心教他，他不肯学。一脉的研究，就这么断了，只剩山顶工坊回收的一点资料，管中窥豹。",
		id = 323712009
	},
	[323712010] = {
		speaker = "我",
		prefab_name = "",
		content = "你对烛的评价也很高啊。",
		id = 323712010
	},
	[323712011] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "她觉醒比我晚，在我这里学过基础的物理和机械。后来她接触到从蓬莱传出来的机关术，决定改变研究方向，最后做出了连我都复制不了的异质序核。",
		id = 323712011
	},
	[323712012] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "天理阁的学员和研究员不少，但像她一样有决心也有天赋走出自己道路的，寥寥无几。",
		id = 323712012
	},
	[323712013] = {
		speaker = "我",
		prefab_name = "",
		content = "……",
		id = 323712013
	},
	[323712014] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "怎么了？",
		id = 323712014
	},
	[323712015] = {
		speaker = "",
		prefab_name = "",
		content = "我没想到烛年纪比你小",
		id = 323712015
	},
	[323712016] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "都是修正者，你看不出来也正常。",
		id = 323712016
	},
	[323712017] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "已经废弃的地方，就不多提了。",
		id = 323712017
	},
	[323712018] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "呵，要我夸夸你吗？",
		id = 323712018
	},
	[323712019] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "走吧，该下山了。交通线我让我那些学生去安排了，我们直接回去就好。",
		id = 323712019
	},
	[323712020] = {
		speaker = "我",
		prefab_name = "",
		content = "说起来，你对这个轩辕计划怎么看？",
		id = 323712020
	},
	[323712021] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "怎么，你觉得有哪里不对吗？",
		id = 323712021
	},
	[323712022] = {
		speaker = "我",
		prefab_name = "",
		content = "没有，只是……感觉是个大事。",
		id = 323712022
	},
	[323712023] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "说大也大，事关整个虚恒的生计。可说小也小，不过是回家而已。",
		id = 323712023
	},
	[323712024] = {
		speaker = "我",
		prefab_name = "",
		content = "回家吗……",
		id = 323712024
	},
	[323712025] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "对人类来说，确实已经过去了两三代人，所以大家有不同的意见。",
		id = 323712025
	},
	[323712026] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "但对我来说……我和庚辰以前就住在玉京，可不就是回家么。",
		id = 323712026
	},
	[323722001] = {
		speaker = "我",
		prefab_name = "",
		content = "上次来这儿遇到智械，这次来这儿遇到视骸。都成废墟了，还是多灾多难……",
		id = 323722001
	},
	[323722002] = {
		speaker = "",
		prefab_name = "",
		content = "和执明一起安装好最后一台报警器，我环顾四周，在旧城区的废墟之间还能看到未被清理的智械残骸。",
		id = 323722002
	},
	[323722003] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "上次？找异质序核那次么？",
		id = 323722003
	},
	[323722004] = {
		speaker = "我",
		prefab_name = "",
		content = "你知道啊？",
		id = 323722004
	},
	[323722005] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "回来以后听陵光说了……这件事，还没跟你说谢谢。",
		id = 323722005
	},
	[323722006] = {
		speaker = "我",
		prefab_name = "",
		content = "都是公事，私底下还说这个干嘛？",
		id = 323722006
	},
	[323722007] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "不止是异质序核，还有烛留下的设备和资料。",
		id = 323722007
	},
	[323722008] = {
		speaker = "我",
		prefab_name = "",
		content = "那些东西很重要吗？",
		id = 323722008
	},
	[323722009] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "机关术的传承断在她那儿，后人想要捡起来就靠那些东西了，你说重不重要？",
		id = 323722009
	},
	[323722010] = {
