	},
	[323722025] = {
		speaker = "",
		prefab_name = "",
		content = "执明咬着嘴唇，面无表情地盯着我，过了好一会儿，她把装报警器的大背包往我怀里一塞，一言不发地朝升降梯走去。",
		id = 323722025
	},
	[323731001] = {
		speaker = "我",
		prefab_name = "",
		content = "你说的「回去」，原来是回这边吗……",
		id = 323731001
	},
	[323731002] = {
		speaker = "",
		prefab_name = "",
		content = "执明像是与施工队交代了几句话，我自己在旁边闲逛，直到执明忙完朝我走过来。",
		id = 323731002
	},
	[323731003] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "想到一些事，还是当面交代比较好。",
		id = 323731003
	},
	[323731004] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "我告诉他们要如何安抚和应对，避免引起冲突。",
		id = 323731004
	},
	[323731005] = {
		speaker = "我",
		prefab_name = "",
		content = "地上还有游民？",
		id = 323731005
	},
	[323731006] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "一直都有，大多是云歌之变时受灾严重的人。他们在灾难中失去了一切，也没有心气搬到五岛重新开始生活，就选择留在地上。",
		id = 323731006
	},
	[323731007] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "但日子总要过下去。走出天灾的阴影以后，他们拾起了地上的产业，结成一个个小聚落，恢复生产，和五岛也有商贸往来。",
		id = 323731007
	},
	[323731008] = {
		speaker = "我",
		prefab_name = "",
		content = "他们没想过再搬到五岛去吗？",
		id = 323731008
	},
	[323731009] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "有，但还有不少人更愿意守着故乡。游民对轩辕计划有抵触的情绪，也是因为这个……",
		id = 323731009
	},
	[323731010] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "毕竟当初我们的确没有选择与他们一起重建家园，而是搬到了天上。",
		id = 323731010
	},
	[323731011] = {
		speaker = "我",
		prefab_name = "",
		content = "这也是你们的故乡，我想他们最后会理解的。",
		id = 323731011
	},
	[323731012] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "说好话的痕迹太重了。",
		id = 323731012
	},
	[323731013] = {
		speaker = "我",
		prefab_name = "",
		content = "好话归好话，至少不是假话。",
		id = 323731013
	},
	[323731014] = {
		speaker = "我",
		prefab_name = "",
		content = "这片废墟，这座城市……你知道，人看着自己熟悉的东西，眼神是不一样的。",
		id = 323731014
	},
	[323731015] = {
		speaker = "",
		prefab_name = "",
		content = "我看着执明，忍不住笑了笑。她一直盯着眼前的断壁残垣，过了好一会儿才意识到我在跟她说话，偏过头，目光与我碰了一下。",
		id = 323731015
	},
	[323731016] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "话多……",
		id = 323731016
	},
	[323731017] = {
		speaker = "我",
		prefab_name = "",
		content = "好吧，那抛开个人情感，轩辕计划也不是临时起意。清理云歌石矿脉的工作很早就开始了吧？",
		id = 323731017
	},
	[323731018] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "嗯，虚恒也好，其他地方也罢，没有完美的环境，只有适应环境改造环境的人。",
		id = 323731018
	},
	[323731019] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "这次搬回地面，就算工程一切顺利，我也没法保证以后不会再出别的问题。到那时，一定又会有人翻今天的旧账吧……",
		id = 323731019
	},
	[323731020] = {
		speaker = "我",
		prefab_name = "",
		content = "历史是个圈，但该做的事总要去做。",
		id = 323731020
	},
	[323731021] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "是这样。环境一变，人也得跟着变，一代人有一代人的问题，哪怕不能相互理解……在做事的人，低着头去做也就是了。",
		id = 323731021
	},
	[323731022] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "你那边呢？夏什瓦特以后，有进展吗？",
		id = 323731022
	},
	[323731023] = {
		speaker = "我",
		prefab_name = "",
		content = "没，所有线索都断了。",
		id = 323731023
	},
	[323731024] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "所以你才这么闲。",
		id = 323731024
	},
	[323731025] = {
		speaker = "我",
		prefab_name = "",
		content = "遇到事情全力以赴，闲下来就不要没事找事，过日子嘛，总要给自己留点余地。",
		id = 323731025
	},
	[323731026] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "你不想没事找事，那我给你找点事，怎么样？",
		id = 323731026
	},
	[323731027] = {
		speaker = "我",
		prefab_name = "",
		content = "听你安排。",
		id = 323731027
	},
	[323731028] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "来朔方坐坐吧，应该就我那里，你没去过了。",
		id = 323731028
	},
	[323731029] = {
		speaker = "我",
		prefab_name = "",
		content = "呃……有事不能在这儿讲吗？",
		id = 323731029
	},
	[323731030] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "这就是我说的「事」……装听不懂吗？",
		id = 323731030
	},
	[323731031] = {
		speaker = "",
		prefab_name = "",
		content = "她伸手来揪我的耳朵，我向后缩了缩脑袋，帽子却被她摘了过去。",
		id = 323731031
	},
	[323731032] = {
		speaker = "我",
		prefab_name = "",
		content = "啊！你偷袭！",
		id = 323731032
	},
	[323731033] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "太晒了，借我戴一会儿。",
		id = 323731033
	},
	[323731034] = {
		speaker = "",
		prefab_name = "",
		content = "我抬头看了看天，太阳不算大，正想嘀咕两句，她却已经走远了……于是只好跟在她后面，一下午时间，总不至于要不回一顶帽子吧？",
		id = 323731034
	},
	[323741001] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "这个啊，这个是「仙人探测器」。",
		id = 323741001
	},
	[323741002] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "只是摄像头啦，我们这几天跑了好几个地方，装了可能有七八台吧……",
		id = 323741002
	},
	[323741003] = {
		speaker = "",
		prefab_name = "",
		content = "看到营地里架着一台球型监控探头，我随口问了一下这么做的用意，毕竟这荒山野岭的似乎没有需要防范的东西，得到的答复却又有些合理。",
		id = 323741003
	},
	[323741004] = {
		speaker = "我",
		prefab_name = "",
		content = "那……那你们探测到什么东西了吗？",
		id = 323741004
	},
	[323741005] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "有是有，不过不是仙人。",
		id = 323741005
	},
	[323741006] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "不对不对，他肯定和仙人有关系，只是我们还没有参透玄机而已。",
		id = 323741006
	},
	[323741007] = {
		speaker = "我",
		prefab_name = "",
		content = "哈？谁啊？",
		id = 323741007
	},
	[323741008] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "一位白胡子老爷爷，乌看他老人家也有仙人之姿~不过比起老师还是差了点。",
		id = 323741008
	},
	[323741009] = {
		speaker = "",
		prefab_name = "",
		content = "我一听就知道是假的，不过看金乌兴致勃勃的样子，便顺着她的话往下问，也弄明白了到底发生了什么。",
		id = 323741009
	},
	[323741010] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "……哎，金乌，好像拍到了！",
		id = 323741010
	},
	[323741011] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "什么什么让乌看看。",
		id = 323741011
	},
	[323741012] = {
		speaker = "",
		prefab_name = "",
		content = "两个人坐在营火边，从「4号探测器」传回的画面里，两人看到一道人影在画面远方一晃而过。",
		id = 323741012
	},
	[323741013] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "哎呦，肯定就是了！这山里除了仙人还能有谁？",
		id = 323741013
	},
	[323741014] = {
		speaker = "",
		prefab_name = "",
		content = "金乌一边说着一边施展出御剑的法术，重明也只好放下监控跟了上去。",
		id = 323741014
	},
	[323741015] = {
		speaker = "",
		prefab_name = "",
		content = "两人在「4号探测器」附近转了一圈，果真找到一座木屋。她们小心翼翼地靠过去，生怕惊动了「仙人」。",
		id = 323741015
	},
	[323741016] = {
		speaker = "",
		prefab_name = "",
		content = "可还没到木屋前，那房门便打开了，两人一下睁大了眼睛，却看到里面走出一个身穿棉袄扛着斧头的老人。",
		id = 323741016
	},
	[323741017] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "啊？",
		id = 323741017
	},
	[323741018] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "乌了个仙人在上，果然返璞归真，道韵天成呀！",
		id = 323741018
	},
	[323741019] = {
		speaker = "",
		prefab_name = "",
		content = "老人怔怔地看着金乌和重明，过了好一会儿终于反应过来，忍不住大笑起来。",
		id = 323741019
	},
	[323741020] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "哈哈哈，好多年没见到来山里找仙人的年轻人了。但我不是什么仙人，我只是个猎户。",
		id = 323741020
	},
	[323741021] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "诶，不是吗？",
		id = 323741021
	},
	[323741022] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "「青冥浩荡不见底，日月照耀金银台。霓为衣兮风为马，云之君兮纷纷而来下。」这仙人的派头，老头子我是一点都沾不上啊。",
		id = 323741022
	},
	[323741023] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "山里那台摄像头是你们的吧？准备得倒是齐全。",
		id = 323741023
	},
	[323741024] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "这么说拍到的果然是您……",
		id = 323741024
	},
	[323741025] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "山里也没别人了。我看到营火，以为有人被困在山里，靠近一看，没人，设备也先进的很，还以为是搞新闻的来了。",
		id = 323741025
	},
	[323741026] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "我这腿脚呢，前几天出门打猎伤着了，不怎么利索，就回来了，没想到你们能找到这儿啊。",
		id = 323741026
	},
	[323741027] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "来吧，天冷，进来坐坐，喝碗姜汤。",
		id = 323741027
	},
	[323751001] = {
		speaker = "",
		prefab_name = "",
		content = "木屋内十分简陋，没有一台电子设备，所有家具都是手工打造，放眼望去满是与世隔绝的质朴。",
		id = 323751001
	},
	[323751002] = {
		speaker = "",
		prefab_name = "",
		content = "老猎户泡了两碗姜汤，递给重明和金乌。两人作为修正者虽然不觉得冷，但出于礼貌还是接到了手里。",
		id = 323751002
	},
	[323751003] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "老爷爷，您为什么一个人住在山里啊？",
		id = 323751003
	},
	[323751004] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "我啊，我从我爷爷那辈开始就住这儿了。原本是个村子呢。",
		id = 323751004
	},
	[323751005] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "以前和你们一样来找神仙的人很多，神仙没找到，倒是把山里的旅游业带起来了。你们在山上看到的一些建筑，都是那时候留下来的。",
		id = 323751005
	},
	[323751006] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "但后来那什么云歌之变以后，昆仑没人来了，山外的城镇也都空了，慢慢的，住在山里的人也都搬走了。",
		id = 323751006
	},
	[323751007] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "十多年前吧，我弟带着弟媳也搬去了天上。他问我要不要跟着去，我说别……你去了大城市，也别告诉别人我在这儿。",
		id = 323751007
	},
	[323751008] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "为什么呀？搬到天上条件可宽松了。",
		id = 323751008
	},
	[323751009] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "这儿不好吗？",
		id = 323751009
	},
	[323751010] = {
		speaker = "",
		prefab_name = "",
		content = "老猎户的笑容悠然自得，抬头指了指外面的茫茫雪山，颇有点挥斥方遒的劲头。",
		id = 323751010
	},
	[323751011] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "昆仑再贫瘠，也是千里山脉，这么大的地界养我一个，那还不是绰绰有余？",
		id = 323751011
	},
	[323751012] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "你们那五岛之上，都没人敢说有我奢侈吧？",
		id = 323751012
	},
	[323751013] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "您这心态倒挺像个仙人的。",
		id = 323751013
	},
	[323751014] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "那我在这深山中住着，也算一种苦修，多少得了些道吧，哈哈。",
		id = 323751014
	},
	[323751015] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "所以，您在山里住了这么多年，都没有见过仙人吗？也不知道长生的秘法？",
		id = 323751015
	},
	[323751016] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "仙人确实是没见过，不过这个长生的法子，还真有。",
		id = 323751016
	},
	[323751017] = {
		speaker = "",
		prefab_name = "",
		content = "金乌和重明对视一眼，都震惊不已，满眼好奇地看着老猎户。",
		id = 323751017
	},
	[323751018] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "……老先生，您要是有长生秘法的线索，可以告诉我吗？我不白要您的好处，我可以开很高的价钱。",
		id = 323751018
	},
	[323751019] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "对对对，她可有钱了。",
		id = 323751019
	},
	[323751020] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "这倒也怪了。你说你们两个小女娃，还这么年轻，怎么就开始惦记长生的法子了？",
		id = 323751020
	},
	[323751021] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "不是我，是我……我认识的人很需要。",
		id = 323751021
	},
	[323751022] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "那需要的人可多了，每天都有人作古，每时都有人盼着长生。",
		id = 323751022
	},
	[323751023] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "那……您要怎么样才愿意告诉我呢？",
		id = 323751023
	},
	[323751024] = {
		speaker = "",
		prefab_name = "",
		content = "老猎户拨弄着柴火，沉默良久，又看了看重明有些彷徨的神情，回头瞅了眼厨房。",
		id = 323751024
	},
	[323751025] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "这样吧，我伤了腿脚，没办法打猎。家里的肉食快吃完了，你们两个小娃娃看着都是有功夫傍身的，帮我打点野味回来，怎么样？",
		id = 323751025
	},
	[323751026] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "……打猎就行了吗？",
