	},
	[323761001] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "这大铁锅炖出来的肉啊，是真不一样，汤汁浓郁，料好入味儿，肉香全都锁得死死的。",
		id = 323761001
	},
	[323761002] = {
		speaker = "",
		prefab_name = "",
		content = "锅铲埋在汤里，缓慢搅动，大开大合，翻起一块块裹着油光肥瘦相间的炖肉。老猎户盛出两盘，递给眼巴巴看着的金乌和重明。",
		id = 323761002
	},
	[323761003] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "姜汤暖胃，但御寒还是要吃饱喝足才行。",
		id = 323761003
