	},
	[323761008] = {
		speaker = "",
		prefab_name = "",
		content = "老猎户给自己也舀了一碗肉，呷了一口汤，鲜得咋舌不已。正闷头吃肉的金乌愣住了，想了好一会儿，慢慢放下碗筷，看上去有些不高兴。",
		id = 323761008
	},
	[323761009] = {
