	},
	[323761012] = {
		speaker = "",
		prefab_name = "",
		content = "重明低头看着碗里的肉汤，默不作声。金乌有些奇怪，伸手在重明面前晃了晃。老猎户却爽朗地大笑起来。",
		id = 323761012
	},
	[323761013] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "歪问题还得用歪理解。看来这位小姑娘是转过弯来了。",
		id = 323761013
	},
	[323761014] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "我也知道……但总要亲自找过。",
		id = 323761014
	},
	[323761015] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "许多事啊，一轮复一轮，就是大伙儿都不信邪。世间若有长生法，哪里还需要在山里躲躲藏藏让人苦寻不得？",
		id = 323761015
	},
	[323761016] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "所谓长生，也就是昨天活着，今天活着，明天也活着，天天如此。",
		id = 323761016
	},
	[323761017] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "人要如何确认自己活着呢，无非就是吃得好饭，睡得好觉，走得好路，五感通明。",
		id = 323761017
	},
	[323761018] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "与其担心生老病死，担心那一日的界限，还不如起来活动活动筋骨，出门看看山河湖海，再回家啊，吃口肉。",
		id = 323761018
	},
	[323761019] = {
		speaker = "老猎户",
		prefab_name = "",
		content = "凡人的「长生」，不就是这么个「求」法么？",
