	[323791031] = {
		speaker = "我",
		prefab_name = "",
		content = "我认不认识不重要，但在剑门关，我也听过一些常曦上仙的故事，说遇到她的人都如沐春风，感觉到清朗和洁净。",
		id = 323791031
