	},
	[323801021] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "品相优劣，味道好坏，都不过是人的一个念头。我吃的是天地生养的灵蕴，不是这个念头。",
		id = 323801021
	},
	[323801022] = {
