	},
	[323801031] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "……是不是钱不够了？",
		id = 323801031
	},
	[323801032] = {
		speaker = "我",
		prefab_name = "",
		content = "……我都带你出来了，身上能没钱吗？",
		id = 323801032
	},
	[323801033] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "哎呦，两位，我摆这个摊也不图多赚多少钱。这袋水果就拿去吧。",
		id = 323801033
	},
	[323801034] = {
		speaker = "我",
		prefab_name = "",
		content = "不是……",
		id = 323801034
	},
	[323801035] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "要是有空，可不可以帮阿姨一个忙？",
		id = 323801035
	},
	[323801036] = {
		speaker = "我",
		prefab_name = "",
		content = "呃，您说。",
		id = 323801036
	},
	[323801037] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "这北征不是调走了不少人嘛，但后方的城关也得有人守呀。我丈夫就被调去守剑门关去了，我又得看着摊子。",
		id = 323801037
	},
	[323801038] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "现在我们在沂山的果园没人打理，下一轮采摘的时候又快到了。如果你们能帮忙打理一下果园，水果可管够。",
		id = 323801038
	},
	[323801039] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "沂山在哪儿？",
		id = 323801039
	},
	[323811001] = {
		speaker = "我",
		prefab_name = "",
		content = "让我看看啊，这《果园种植管理手册》还挺长……",
		id = 323811001
	},
	[323811002] = {
		speaker = "",
		prefab_name = "",
		content = "按照水果摊老板娘给的路线，我和望舒登上燕沂城西边的一座小山，顺利找到了这座果园。",
		id = 323811002
	},
	[323811003] = {
		speaker = "",
		prefab_name = "",
		content = "当我还在翻看老板娘给我的「参考材料」时，望舒已经提着一只篮子，走进树林拨弄起树枝了。",
		id = 323811003
	},
	[323811004] = {
		speaker = "我",
		prefab_name = "",
		content = "哦，忘了诺尔薇教过你这些。",
		id = 323811004
	},
	[323811005] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "你要是不会，看着就好了。",
		id = 323811005
	},
	[323811006] = {
		speaker = "我",
		prefab_name = "",
		content = "可别小看我能一边翻说明书一边开飞机的悟性啊。",
		id = 323811006
	},
	[323811007] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "还有这事？",
		id = 323811007
	},
	[323811008] = {
		speaker = "我",
		prefab_name = "",
		content = "当然没有……那怎么办？我要是什么都不干，我来干嘛？",
		id = 323811008
	},
	[323811009] = {
		speaker = "我",
		prefab_name = "",
		content = "哦！我知道了，我是来制止你偷吃的。",
		id = 323811009
	},
	[323811010] = {
		speaker = "",
		prefab_name = "",
		content = "望舒不知从哪里捡来一根又长又直的树枝，敲了一下我的脑袋，将她手里装满的果篮递给我。",
		id = 323811010
	},
	[323811011] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "东边有一片果树倒了，你去看看。",
		id = 323811011
	},
	[323811012] = {
		speaker = "我",
		prefab_name = "",
		content = "你又知道了……算了我不问了。为什么不一起去呢？",
		id = 323811012
	},
	[323811013] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "……好，一起去。",
		id = 323811013
	},
	[323811014] = {
		speaker = "",
		prefab_name = "",
		content = "起初我不知道望舒为什么答应得这么干脆。直到来到那一片或被推倒或被折断的树林附近，弥弥尔系统的骸能警报开始响起时，我才恍然大悟。",
		id = 323811014
	},
	[323811015] = {
		speaker = "我",
		prefab_name = "",
		content = "这里还有视骸？",
		id = 323811015
	},
	[323811016] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "大荒也是盖亚的一部分。",
		id = 323811016
	},
	[323811017] = {
		speaker = "我",
		prefab_name = "",
		content = "不，我意思是「离燕沂城这么近的地方」。我问过秋丹，感觉燕沂城缺乏对视骸的防护，会不会出问题。",
		id = 323811017
	},
	[323811018] = {
		speaker = "我",
		prefab_name = "",
		content = "他说早些年确实提防过，但大荒之中视骸本来就少，多数都在北边和游荡的荒兽掐架。燕沂城附近已经很多年没有出现过视骸了。",
		id = 323811018
	},
	[323811019] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "但这的确是骸能，不会有错。",
		id = 323811019
	},
	[323811020] = {
		speaker = "我",
		prefab_name = "",
		content = "……总之追踪一下看看吧。",
		id = 323811020
	},
	[323812001] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "就这些了。",
		id = 323812001
	},
	[323812002] = {
		speaker = "",
		prefab_name = "",
		content = "弥弥尔系统扫描下的所有骸能信号源消失，我收起枪，回忆了一下刚才并不算激烈的战斗，有些困惑地摇摇头。",
		id = 323812002
	},
	[323812003] = {
		speaker = "我",
		prefab_name = "",
		content = "就这么零星几只，不像是被操控。可要凭本能行事，又不去燕沂城里闹事，就在这里当山大王，怎么会有这么怂的视骸？",
		id = 323812003
	},
	[323812004] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "你见过很多视骸？",
		id = 323812004
	},
	[323812005] = {
		speaker = "我",
		prefab_name = "",
		content = "很不幸，是的。没有人——不包括修正者——比我更懂——单说这个纪元最新的情况——视骸。",
		id = 323812005
	},
	[323812006] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "我知道得不多。这种情况严重吗？",
		id = 323812006
	},
	[323812007] = {
		speaker = "我",
		prefab_name = "",
		content = "不严重，完全不严重。",
		id = 323812007
	},
	[323812008] = {
		speaker = "我",
		prefab_name = "",
		content = "不过就你这个一剑一块骸能核心的手法，真对视骸不熟吗？",
		id = 323812008
	},
	[323812009] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "「杀死」这件事，只有一个通则。找到能量最密的部位，斩断，就好了。",
		id = 323812009
	},
	[323812010] = {
		speaker = "我",
		prefab_name = "",
		content = "能量最密的部位……所以你敲我脑袋实际上是想——",
		id = 323812010
	},
	[323812011] = {
		speaker = "",
		prefab_name = "",
		content = "树枝又照我脑袋上敲了一下，动作很干脆，但力道非常轻，只是感觉被敲过的地方头发痒痒的，跟「杀死」显然不挂钩。",
		id = 323812011
	},
	[323812012] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "回去吧。",
		id = 323812012
	},
	[323812013] = {
		speaker = "我",
		prefab_name = "",
		content = "等等，这么多被推倒的树，总得处理一下。折断的没办法，只能挖掉根重新种了。推倒的这些，根系没暴露太久，也许还有得救。",
		id = 323812013
	},
	[323812014] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "你还会种树？",
		id = 323812014
	},
	[323812015] = {
		speaker = "",
		prefab_name = "",
		content = "我神秘一笑，亮出终端上的人工智能问答页面。",
		id = 323812015
	},
	[323812016] = {
		speaker = "我",
		prefab_name = "",
		content = "它会，就等于我会。\n来，那边那棵，帮我把它扶起来。",
		id = 323812016
	},
	[323812017] = {
		speaker = "",
		prefab_name = "",
		content = "我们将几棵受损不严重的果树扶正，将根系埋进土里，再将那些折断的果树连根挖出来，捡来散落在地上的果子，种进原位。",
		id = 323812017
	},
	[323812018] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "这样就能活了吗？",
		id = 323812018
	},
	[323812019] = {
		speaker = "我",
		prefab_name = "",
		content = "不好说，但至少我们能做的都已经做了。往好了想，如果我们今天不来，它们就连重新成活的机会都没有了。",
		id = 323812019
	},
	[323812020] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "尽人事，知天命。",
		id = 323812020
	},
	[323812021] = {
		speaker = "我",
		prefab_name = "",
		content = "是啊，多少事都是这样呢……",
		id = 323812021
	},
	[323812022] = {
		speaker = "",
		prefab_name = "",
		content = "看着眼前的一排排果树，我的确想象不到它们以后会怎么样，是怀着短暂的希望一同枯死，还是能等来下一次开花结果。",
		id = 323812022
	},
	[323812023] = {
		speaker = "",
		prefab_name = "",
		content = "看着眼前的一排排果树，像是我们在旁观这个世界。",
		id = 323812023
	},
	[323821001] = {
		speaker = "我",
		prefab_name = "",
		content = "……果园的情况大概就是这样。摘下来的果子全放进果园边山的保鲜库了。",
		id = 323821001
	},
	[323821002] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "唉，天灾人祸嘛，损失几棵树也难免。",
		id = 323821002
	},
	[323821003] = {
		speaker = "",
		prefab_name = "",
		content = "回到燕沂城的时候已经临近傍晚，水果摊还没收摊。摊主阿姨检查了一下我们带回来的样果，看上去十分满意，将这一篮样果也送给了我们。",
		id = 323821003
	},
	[323821004] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "晚上宵禁，再过一小时我就收摊了。摊子上的果子都卖不完，这一篮我提回去也是送人或者自己吃了，你们就收着吧。",
		id = 323821004
	},
	[323821005] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "谢谢。",
		id = 323821005
	},
	[323821006] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "不用客气。基本的吃穿用度都有分配，我种点水果摆个摊也是想着为燕沂城做点事。",
		id = 323821006
	},
	[323821007] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "你们帮我看园子，我给你们一点水果，也算是互通有无。大荒物资本来就匮乏，不这样互帮互助，大家日子都不好过。",
		id = 323821007
	},
	[323821008] = {
		speaker = "我",
		prefab_name = "",
		content = "物资匮乏？阿姨，您平时会有这种感觉吗？",
		id = 323821008
	},
	[323821009] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "倒也没什么实际的感觉……年轻人啊，你们去过虚恒纪念馆吗？",
		id = 323821009
	},
	[323821010] = {
		speaker = "我",
		prefab_name = "",
		content = "还没去过，我们是从剑门关那边来的。",
		id = 323821010
	},
	[323821011] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "哦，难怪。在燕沂城啊，希文牧守，也就是燕沂城的大长官，每年都会在纪念馆举办还乡的宣传教育活动。",
		id = 323821011
	},
	[323821012] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "我就听说，咱们的虚恒老家，物阜民丰，粮食亩产得有这儿的两三倍，地界又大，好山好水。这么比下来，大荒可不是物资匮乏么。",
		id = 323821012
	},
	[323821013] = {
		speaker = "",
		prefab_name = "",
		content = "我愣了一会儿，慢慢明白过来。八十多年前大荒绝通时，云歌之变还没发生。所以在大荒传承中的「虚恒」，应该还是没有经历过那场灾难的样子。",
		id = 323821013
	},
	[323821014] = {
		speaker = "我",
		prefab_name = "",
		content = "那……您，或者您身边的其他人，对「还乡」这件事是怎么看的呢？",
		id = 323821014
	},
	[323821015] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "肯定都想回去啊，年年听说故乡好，谁不想回去呢？",
		id = 323821015
	},
	[323821016] = {
		speaker = "我",
		prefab_name = "",
		content = "可八十多年过去了，您有没有担心过，可能故乡已经变得不一样了？",
		id = 323821016
	},
	[323821017] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "担心啊，肯定担心。那句话怎么说的来着……「近乡情更怯」，是吧……",
		id = 323821017
	},
	[323821018] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "不过现在想这个还太早了，谁知道什么时候能回去呢？我爷爷奶奶没等到，我爹娘也没等到，我怕我也等不到了，只希望我家娃娃能等到那天……",
		id = 323821018
	},
	[323821019] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "有时想想，就算发现虚恒已经大变样了，已经适应不了那边的生活了，至少也算知道故乡是怎么回事儿，心里能踏实。",
		id = 323821019
	},
	[323821020] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "大荒要打仗啊，隔三差五地打……多少人上了战场，一去就再没回来。住隔壁的邻居，来买水果的熟客……太多了。",
		id = 323821020
	},
	[323821021] = {
		speaker = "水果摊阿姨",
		prefab_name = "",
		content = "想这想那的……哪有过个踏实日子重要？",
		id = 323821021
	},
	[323821022] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "……在想什么？",
		id = 323821022
	},
	[323821023] = {
		speaker = "",
		prefab_name = "",
		content = "望舒将水果塞进冰箱，见我靠在窗户边发呆，拿了一盒草莓，走到我旁边，把盒子放在窗台上，与我并排站着。",
		id = 323821023
	},
	[323821024] = {
		speaker = "我",
		prefab_name = "",
		content = "在想……这草莓不错。",
		id = 323821024
	},
	[323821025] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "不想说就算了。",
		id = 323821025
	},
	[323821026] = {
		speaker = "我",
		prefab_name = "",
		content = "没没没……在想一些可能不该我一个人空想的事情。",
		id = 323821026
	},
	[323821027] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "你很喜欢关心其他人的事。",
		id = 323821027
	},
	[323821028] = {
		speaker = "我",
		prefab_name = "",
		content = "哈哈，确实经常被人这么说……呃，为什么忽然这么说？",
		id = 323821028
	},
	[323821029] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "不过，让大荒回到虚恒，不是你一个人的事，也不存在「应不应该」。",
		id = 323821029
	},
	[323821030] = {
		speaker = "",
		prefab_name = "",
		content = "嘴里的草莓差点噎住，我瞪大眼睛看着她。她又拿了一颗草莓放到我手里，然后依旧若无其事地望向窗外。",
		id = 323821030
	},
	[323821031] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "所以我说，你不想说就算了。",
		id = 323821031
	},
	[323821032] = {
		speaker = "我",
		prefab_name = "",
		content = "……这件事关系重大，你出门可别乱说。而且就算想做，也不是我一个人能决定的……或者说决定权跟我就没关系。",
		id = 323821032
	},
	[323821033] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "但有决定权的人不知道大荒的情况，你知道了，看到了也听到了。",
		id = 323821033
	},
	[323821034] = {
		speaker = "我",
		prefab_name = "",
		content = "……",
		id = 323821034
	},
	[323821035] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "反正，需要帮忙，告诉我就好。",
		id = 323821035
	},
	[323821036] = {
		speaker = "",
		prefab_name = "",
