	},
	[933011305] = {
		speaker = "我",
		prefab_name = "",
		content = "以前你想做什么事，都会直接说出来，冒冒失失的，不说出来憋得慌。",
		id = 933011305
	},
	[933011306] = {
		speaker = "我",
		prefab_name = "",
		content = "现在么，小心思变多了，心里有话知道藏着了。",
		id = 933011306
	},
	[933011307] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "你也看得出我在想什么吗？",
		id = 933011307
	},
	[933011308] = {
		speaker = "我",
		prefab_name = "",
		content = "哼哼，别以为只有你观察得那么仔细。要知道，你看着我的时候，我也在看着你啊。",
		id = 933011308
	},
	[933011309] = {
		speaker = "",
		prefab_name = "",
		content = "车子开到一处岔路口，我关掉导航，向右变道，驶离了回深空之眼的主干道。",
		id = 933011309
	},
	[933011310] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "管理员，走错路了！",
		id = 933011310
	},
	[933011311] = {
		speaker = "我",
		prefab_name = "",
		content = "没错，这条路去海边。",
		id = 933011311
	},
	[933011312] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "……诶？",
		id = 933011312
	},
	[933011313] = {
		speaker = "我",
		prefab_name = "",
		content = "从能看到海开始，你就一直盯着海滩看……要不怎么说，你心里有话知道藏着呢？",
		id = 933011313
	},
	[933011314] = {
		speaker = "",
		prefab_name = "",
		content = "艾因索菲的西海岸线很长，找到一处只有我们两人的僻静沙滩并不算难事。",
		id = 933011314
	},
	[933011315] = {
		speaker = "",
		prefab_name = "",
		content = "推开车门，海风扑面而来，能触到晚秋的凉爽与夕阳的温煦，也能嗅到草木的清甜与海水的咸涩。",
		id = 933011315
	},
	[933011316] = {
		speaker = "",
		prefab_name = "",
		content = "我拿了两罐饮料，和薇儿一起默契地脱下鞋子，踩上沙滩开始漫步，在身后留下两串并排的、浅浅的足迹。",
		id = 933011316
	},
	[933011317] = {
		speaker = "",
		prefab_name = "",
		content = "足迹像是起伏的海浪，从东向西蜿蜒。脚下的沙子变得紧实湿润，我们就这样一步一步，慢慢追着退去的潮水，直到它打湿我们的脚踝。",
		id = 933011317
	},
	[933011318] = {
		speaker = "",
		prefab_name = "",
		content = "直到夕阳变成了沙子的颜色，铺在海面上，四面八方都溢满了灿烂的金辉，包裹住我们牵着手的轮廓。",
		id = 933011318
	},
	[933011319] = {
		speaker = "我",
		prefab_name = "",
		content = "给，青苹果味的。",
		id = 933011319
	},
	[933011320] = {
		speaker = "",
		prefab_name = "",
		content = "我扯开易拉罐的拉环，将其中一罐递给薇儿。她接到手里，却没有喝，低头看着罐子口，像是在听里面气泡哔哔啵啵的响声。",
		id = 933011320
	},
	[933011321] = {
		speaker = "我",
		prefab_name = "",
		content = "怎么了，宴会上吃得太饱了？",
		id = 933011321
	},
	[933011322] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "饮料才不占肚子……",
		id = 933011322
	},
	[933011323] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "管理员，丽莎学姐问她什么时候能参加我的婚礼的时候，你怎么没说话？",
		id = 933011323
	},
	[933011324] = {
		speaker = "我",
		prefab_name = "",
		content = "你回答得挺好，就不用我替你圆场了吧？",
		id = 933011324
	},
	[933011325] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "不对，你肯定有话想说。",
		id = 933011325
	},
	[933011326] = {
		speaker = "我",
		prefab_name = "",
		content = "……所以，你想说的话就是你觉得我有我想说的话？",
		id = 933011326
	},
	[933011327] = {
		speaker = "",
		prefab_name = "",
		content = "薇儿点点头，笃信地看着我。我默默叹了口气，感慨于薇儿深藏在马虎表现下的敏感。",
		id = 933011327
	},
	[933011328] = {
		speaker = "我",
		prefab_name = "",
		content = "昨天休找我了，提到你参加同学婚宴的事。",
		id = 933011328
	},
	[933011329] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "休老师吗……她是不是说，再过几年我就没法再和这些同学聚会了？",
		id = 933011329
	},
	[933011330] = {
		speaker = "我",
		prefab_name = "",
		content = "你怎么……",
		id = 933011330
	},
	[933011331] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "我猜应该是说这个……",
		id = 933011331
	},
	[933011332] = {
		speaker = "",
		prefab_name = "",
		content = "罐子里的气泡声弱下去一些，薇儿低头喝了一口，晃了晃罐子，气泡重新翻涌起来。",
		id = 933011332
	},
	[933011333] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "其实这一年，我经常观察身边的前辈，希望能成为更加出色的修正者。",
		id = 933011333
	},
	[933011334] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "我学到了很多，但也注意到了……觉醒越早的前辈，就越少在社会上活动，和普通人类的来往也越少越浅。",
		id = 933011334
	},
	[933011335] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "其实是很简单就能想明白的道理。才过了不到两年，比安卡她们就完全不一样了。",
		id = 933011335
	},
	[933011336] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "再过几年，她们都到了当妈妈的年纪……或者更久一些，她们的子女看上去都和我一样大了，我还怎么见她们……",
		id = 933011336
	},
	[933011337] = {
		speaker = "我",
		prefab_name = "",
		content = "……我一路上都在想该怎么说服你接受这个事实，原来你已经明白了。",
		id = 933011337
	},
	[933011338] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "虽然明白了，但还是会觉得有点害怕吧，或者说，又有点羡慕……",
		id = 933011338
	},
	[933011339] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "比起成为修正者的时间，我作为一个普通人的时间要长得多。上中学的时候和大家一起参加社团，一起写作业，出去玩……都像是昨天才发生的事。",
		id = 933011339
	},
	[933011340] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "丽莎学姐还有比安卡她们，可以把这些回忆和感情一直延续下去，就像婚礼宣誓那样，「直到永远」。",
		id = 933011340
	},
	[933011341] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "但是……我可以吗？感觉它们只会离我越来越远……",
		id = 933011341
	},
	[933011342] = {
		speaker = "我",
		prefab_name = "",
		content = "薇儿，我想你或许误会了一件事。",
		id = 933011342
	},
	[933011343] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "……诶？",
		id = 933011343
	},
	[933011344] = {
		speaker = "我",
		prefab_name = "",
		content = "誓言并不是绝对会实现的保证，而是想要将其实现的约定。",
		id = 933011344
	},
	[933011345] = {
		speaker = "我",
		prefab_name = "",
		content = "正因为人的一生会遭遇各种各样的困难，留下各种各样的遗憾，人们才会许下誓言。",
		id = 933011345
	},
	[933011346] = {
		speaker = "我",
		prefab_name = "",
		content = "因为誓言的存在，人们才会有坚持下去的力量，才会相信，当初与自己一同立下誓言的人，也正在与自己一同努力着。",
		id = 933011346
	},
	[933011347] = {
		speaker = "我",
		prefab_name = "",
		content = "这和我们是人类还是修正者无关，因为我们怀有的记忆和感情是相通的，想要将它们延续下去的想法也是相通的。",
		id = 933011347
	},
	[933011348] = {
		speaker = "我",
		prefab_name = "",
		content = "所以，没有什么「可不可以」，只有你想不想去做。而且，还是那句话——",
		id = 933011348
	},
	[933011349] = {
		speaker = "",
		prefab_name = "",
		content = "我从口袋里摸出易拉罐的拉环，朝薇儿单膝跪地，将拉环像是戒指般捧在手心。",
		id = 933011349
	},
	[933011350] = {
		speaker = "我",
		prefab_name = "",
		content = "薇儿小姐，你是否愿意让我陪在你身边，不管想要做什么，都互相支持，互相帮助，直到永远？",
		id = 933011350
	},
	[933011351] = {
		speaker = "",
		prefab_name = "",
		content = "薇儿怔怔地看着那枚拉环，直到松软的沙地忽然塌下去一块，险些让我摔到一边，她才反应过来似地，把我扶住，然后噗嗤一声笑了出来。",
		id = 933011351
	},
	[933011352] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "我又不是小孩子了。还想用这招来哄我……",
		id = 933011352
	},
	[933011353] = {
		speaker = "",
		prefab_name = "",
		content = "嘴上这么说着，但薇儿还是拉住了我的手，郑重其事地让我为她戴上这枚「指环」。",
		id = 933011353
	},
	[933011354] = {
		speaker = "我",
		prefab_name = "",
		content = "哎，你还没回答呢。",
		id = 933011354
	},
	[933011355] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "……我、我当然愿意了。",
		id = 933011355
	},
	[933011356] = {
		speaker = "",
		prefab_name = "",
		content = "我们笑着，继续说着无关紧要的话语，牵手走在黄昏的海滩上，直到太阳缓缓坠入海中。",
		id = 933011356
	},
	[933011357] = {
		speaker = "",
		prefab_name = "",
		content = "走得有些累了，我们便一同坐在沙滩上，望向夜空中的群星。",
		id = 933011357
	},
	[933011358] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "啊，那个是不是你教过我的，夏季大三角？",
		id = 933011358
	},
	[933011359] = {
		speaker = "",
		prefab_name = "",
		content = "薇儿靠在我的肩上，伸手指向空中那宛如「M」形排列的星座。",
		id = 933011359
	},
	[933011360] = {
		speaker = "我",
		prefab_name = "",
		content = "不是不是，方位都错了。而且现在不都初秋了吗。",
		id = 933011360
	},
	[933011361] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "诶……星星真难认。",
		id = 933011361
	},
	[933011362] = {
		speaker = "我",
		prefab_name = "",
		content = "听好了，我重新教你一次。你刚才看见的是仙后座……",
		id = 933011362
	},
	[933011363] = {
		speaker = "",
		prefab_name = "",
		content = "星座小课堂持续了不到半个小时，我身边便传来了平稳的呼吸声。",
		id = 933011363
	},
	[933011364] = {
		speaker = "我",
		prefab_name = "",
		content = "算了，就让她好好睡吧。",
		id = 933011364
	},
	[933011365] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "要是能……就好了……",
		id = 933011365
	},
	[933011366] = {
		speaker = "",
		prefab_name = "",
		content = "从耳边传来了薇儿那模糊不清的梦呓，好奇心让我忍不住集中精神，尝试听清她究竟在说些什么。",
		id = 933011366
	},
	[933011367] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "不管是现在，还是未来，一直……和你在一起……",
		id = 933011367
	},
	[933011368] = {
		speaker = "",
		prefab_name = "",
		content = "握紧她的手。",
		id = 933011368
	},
	[933011369] = {
		speaker = "我",
		prefab_name = "",
		content = "嗯，我也这么想。",
		id = 933011369
	},
	[933011370] = {
		speaker = "",
		prefab_name = "",
		content = "在夜晚的凉意沁入身体之前，我载着睡着的薇儿回到了公司。",
		id = 933011370
	},
	[933011371] = {
		speaker = "",
		prefab_name = "",
		content = "已经向大国主拖了一天，我不敢再耽搁同步率测试的事，第二天下午如约拉着薇儿跑到隐科组。",
		id = 933011371
	},
	[933011372] = {
		speaker = "",
		prefab_name = "",
		content = "果然，这次海姆达尔也在。我们进门时，她似乎正与大国主争论着什么。",
		id = 933011372
	},
	[933011373] = {
		speaker = "",
		prefab_name = "",
		content = "注意到我们的到来，她们很快停止了争论，我只是依稀听到「灵魂连接」、「潜意识协同」、「数据保护」之类让人半懂不懂的词。",
		id = 933011373
	},
	[933011374] = {
		speaker = "我",
		prefab_name = "",
		content = "……需要我参与讨论吗？",
		id = 933011374
	},
	[933011375] = {
		speaker = "海姆达尔",
		prefab_name = "1033ui_story",
		content = "只是一些我和大国主还没弄明白的技术细节……先进行测试吧。",
		id = 933011375
	},
	[933011376] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "我优化过的算法，同步率应该能到96.5%。",
		id = 933011376
	},
	[933011377] = {
		speaker = "海姆达尔",
		prefab_name = "1033ui_story",
		content = "没事，要是跌了，我有上个版本算法的备份。",
		id = 933011377
	},
	[933011378] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "没事，要是跌了，我还有「激光改良版」和「塔罗牌试验版」。",
		id = 933011378
	},
	[933011379] = {
		speaker = "",
		prefab_name = "",
		content = "没人搭理捧着数据盘跃跃欲试的大国主。",
		id = 933011379
	},
	[933011380] = {
		speaker = "",
		prefab_name = "",
		content = "薇儿登上训练场，我激活弥弥尔系统。这样的战术训练我们已经做过上千次，不需要像都还是新人的时候那样做一大堆准备。",
		id = 933011380
	},
	[933011381] = {
		speaker = "",
		prefab_name = "",
		content = "但这次比起那上千次似乎又有些不同。即便差异非常微小，我很确信一些细节处的配合变得更加流畅了。",
		id = 933011381
	},
	[933011382] = {
		speaker = "海姆达尔",
		prefab_name = "1033ui_story",
		content = "……好了，可以结束了。",
		id = 933011382
	},
	[933011383] = {
		speaker = "我",
		prefab_name = "",
		content = "怎么样？",
		id = 933011383
	},
	[933011384] = {
		speaker = "海姆达尔",
		prefab_name = "1033ui_story",
		content = "大国主，你刚才说同步率可以到多少？",
		id = 933011384
	},
	[933011385] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "唔……96.5%。这是理论上。心链那么复杂，搭建过程出点问题，同步率丢失一点点也很正常……",
		id = 933011385
	},
	[933011386] = {
		speaker = "海姆达尔",
		prefab_name = "1033ui_story",
		content = "那为什么峰值能到97.1%？",
		id = 933011386
	},
	[933011387] = {
		speaker = "",
		prefab_name = "",
		content = "我和大国主都愣住了，刚跑过来的薇儿也愣住了，我们一同围到海姆达尔旁边。",
		id = 933011387
	},
	[933011388] = {
		speaker = "",
		prefab_name = "",
		content = "屏幕上那条小幅震荡但总体平稳的同步率曲线，确实有一大半都越过了97%的水平线。",
