	[933011466] = {
		speaker = "",
		prefab_name = "",
		content = "我低头看着自己的双手，轻轻握了握，好像在用「握住」这个动作来表现「信任」，进而尝试激发一些联想一样。",
		id = 933011466
	},
	[933011467] = {
		speaker = "",
		prefab_name = "",
		content = "看上去有些荒唐……但肢体动作之所以有时能比语言更能精确地表达出我们的情绪，正是因为他们通过潜意识关联到了我们过去表达出类似情绪的记忆。",
		id = 933011467
	},
	[933011468] = {
		speaker = "我",
		prefab_name = "",
		content = "这是在……",
		id = 933011468
	},
	[933011469] = {
		speaker = "",
		prefab_name = "",
		content = "像是小心翼翼地握住短暂出现在我脑海中的既视感，我微微曲起自己的手指，慢慢睁大了眼睛，终于明白了自己为什么会下意识做出这样的动作。",
		id = 933011469
	},
	[933011470] = {
		speaker = "我",
		prefab_name = "",
		content = "……是啊，你在乎的「信任」，你想要的「永恒」……",
		id = 933011470
	},
	[933011471] = {
		speaker = "我",
		prefab_name = "",
		content = "「誓言并不是绝对会实现的保证，而是想要将其实现的约定。」\n亏我还跟你这么说呢……",
		id = 933011471
	},
	[933011472] = {
		speaker = "",
		prefab_name = "",
		content = "恍然大悟后，我急忙转过身，半趴在桌上，一个主意很快在脑海中成型，于是我飞快翻出了休的通讯号码。",
		id = 933011472
	},
	[933011473] = {
		speaker = "我",
		prefab_name = "",
		content = "休，能帮我一个忙吗？多帮我联系几个人……记得保密。",
		id = 933011473
	},
	[933011474] = {
		speaker = "（海姆达尔）",
		prefab_name = "",
		content = "「但其实这是违背我们本性的……就像人大多都有不想被他人知晓的小秘密一样，我们总会下意识地保护一部分『自我』。」",
		id = 933011474
	},
	[933011475] = {
		speaker = "（海姆达尔）",
		prefab_name = "",
		content = "「这种深藏于潜意识中的的细微抗拒，就会像一道道无形的防火墙，阻止两个灵魂数据进行最深层次的链接。」",
		id = 933011475
	},
	[933011476] = {
		speaker = "（海姆达尔）",
		prefab_name = "",
		content = "「虽然只是一点小小的分歧，很快就能经过商量达成一致，但它出现的一瞬间，你们互相之间就形成了抗拒，灵魂链接也会因此断开。」",
		id = 933011476
	},
	[933011477] = {
		speaker = "（海姆达尔）",
		prefab_name = "",
		content = "「这是来自潜意识的，基于自我认知做出的判断，几乎不可能规避。因为『自我意识』本就是为了与他人划开界限而存在的。」",
		id = 933011477
	},
	[933011478] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "唔……",
		id = 933011478
	},
	[933011479] = {
		speaker = "",
		prefab_name = "",
		content = "迷迷糊糊地睁开眼睛，从窗帘的缝隙间望出去，天已经亮了。",
		id = 933011479
	},
	[933011480] = {
		speaker = "",
		prefab_name = "",
		content = "薇儿抱着被子靠坐在床头，一边回想着昨天听到的那些话，一边犹豫着该不该起床。",
		id = 933011480
	},
	[933011481] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "……管理员也是这么想的吗？",
		id = 933011481
	},
	[933011482] = {
		speaker = "我",
		prefab_name = "",
		content = "薇儿，起床了吗？",
		id = 933011482
	},
	[933011483] = {
		speaker = "",
		prefab_name = "",
		content = "门铃声吓了薇儿一跳。听到我的声音，她才慢慢放松下来，按下床头的按钮，为我开了门。",
		id = 933011483
	},
	[933011484] = {
		speaker = "我",
		prefab_name = "",
		content = "没躲在被窝里，醒了有一会儿了吧？",
		id = 933011484
	},
	[933011485] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "昨天晚上没怎么睡……今天不是休息日吗？你怎么起这么早？",
		id = 933011485
	},
	[933011486] = {
		speaker = "我",
		prefab_name = "",
		content = "正因为是休息日，所以才有大把时间可以自由安排啊。",
		id = 933011486
	},
	[933011487] = {
		speaker = "我",
		prefab_name = "",
		content = "起床吧，收拾收拾，我们出发。",
		id = 933011487
	},
	[933011488] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "出发……去哪儿啊？",
		id = 933011488
	},
	[933011489] = {
		speaker = "我",
		prefab_name = "",
		content = "你认识的地方，到了你就知道了。",
		id = 933011489
	},
	[933011490] = {
		speaker = "",
		prefab_name = "",
		content = "虽然看上去十分疑惑，但薇儿还是跟我下了楼。坐上车以后，她看到后座上堆着许多包装精美的礼盒，好奇地趴在座椅上翻看着它们。",
		id = 933011490
	},
	[933011491] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "茶叶、牛奶、水果、补品，还有最新款的保洁智械和按摩仪……",
		id = 933011491
	},
	[933011492] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "管理员，我们要去看望老人吗？",
		id = 933011492
	},
	[933011493] = {
		speaker = "我",
		prefab_name = "",
		content = "嗯……这么说也没错。",
		id = 933011493
	},
	[933011494] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "哦，我知道了，是接替了圣索菲娅医疗中心的那家疗养院吧？我认识的地方，还有老人，也就只有那儿了。",
		id = 933011494
	},
	[933011495] = {
		speaker = "我",
		prefab_name = "",
		content = "猜得这么快？想不到别的地方了？",
		id = 933011495
	},
	[933011496] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "嗯？还有哪儿？",
		id = 933011496
	},
	[933011497] = {
		speaker = "",
		prefab_name = "",
		content = "我笑了笑，没说话，驱车前往墨兰德市。",
		id = 933011497
	},
	[933011498] = {
		speaker = "",
		prefab_name = "",
		content = "伴随着窗外的景色不断变换，熟悉的城镇逐渐映入我们的眼帘。薇儿望着街景，脸上渐渐露出怀念的神情。",
		id = 933011498
	},
	[933011499] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "啊，那家老面包店，现在还开着呢。",
		id = 933011499
	},
	[933011500] = {
		speaker = "我",
		prefab_name = "",
		content = "我记得……你说我以前带你去吃过。店主时不时会做些长相奇形怪状的新品拿出来卖，很受孩子们喜欢。",
		id = 933011500
	},
	[933011501] = {
		speaker = "",
		prefab_name = "",
		content = "和煦的晨光慵懒地洒在街道上，像是故乡的歌谣，熟悉又亲近，与总是繁忙无比的核心城犹如两个世界。",
		id = 933011501
	},
	[933011502] = {
		speaker = "",
		prefab_name = "",
		content = "淡淡的香气从街角传来，仿佛带着记忆的温度，让少女回忆起儿时曾经有过的，那自然而轻盈的悠闲感。",
		id = 933011502
	},
	[933011503] = {
		speaker = "",
		prefab_name = "",
		content = "薇儿深深吸了一口气，那混合着烤麦香与甜腻奶油的空气，似乎拥有奇特的魔力，让她因一夜未眠而微微低垂的眉角，终于缓缓舒展开来。",
		id = 933011503
	},
	[933011504] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "对对对，你第一次捧着「彩虹面包」回来的时候，我都看呆了。",
		id = 933011504
	},
	[933011505] = {
		speaker = "我",
		prefab_name = "",
		content = "我想了好久怎么才能把面包做成彩虹色，后来上网查了一下，其实是用果酱涂出来的。",
		id = 933011505
	},
	[933011506] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "小时候拿到面包就吃了，哪里会注意到这个……",
		id = 933011506
	},
	[933011507] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "管理员，前面就是你带我去吃第一顿烤肉的那家店了……咦？",
