		id = 933011696
	},
	[933011697] = {
		speaker = "",
		prefab_name = "",
		content = "明明本打算直入正题，但话语却不断从心底涌出。",
		id = 933011697
	},
	[933011698] = {
		speaker = "我",
		prefab_name = "",
		content = "我发自真心的觉得，在我身边的人是你，真是太好了。",
		id = 933011698
	},
	[933011699] = {
		speaker = "",
		prefab_name = "",
		content = "和薇儿一起度过的那些日子，她的声音，她的表情——就像是走马灯一样在脑海中闪过。",
		id = 933011699
	},
	[933011700] = {
