		prefab_name = "",
		content = "您有什么安排？",
		id = 324031109
	},
	[324031110] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "囚云山的对接机关需要两侧同时启动，过程中若是发生问题，也需要两侧一同排查。",
		id = 324031110
	},
	[324031111] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "现在后土被困，大荒的对接机关无人操控，能去大荒的又只有你……",
		id = 324031111
	},
	[324031112] = {
		speaker = "我",
		prefab_name = "",
		content = "要我学会操作对接机关吗？",
		id = 324031112
	},
	[324031113] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "正是。大荒绝通时，后土把她的两个小跟班，无咎和必安，留在了这边。",
		id = 324031113
	},
	[324031114] = {
		speaker = "羲和",
		prefab_name = "10039ui_story",
		content = "她们姐妹俩常年住在囚云山上。机关的用法，后土都教过她们。你去找她们学，十天时间，看你悟性了。",
		id = 324031114
	},
	[324031115] = {
		speaker = "我",
