	},
	[324051012] = {
		speaker = "我",
		prefab_name = "",
		content = "我要是知道就好了……就是因为不知道，所以才想两地重连，一起想办法。",
		id = 324051012
	},
	[324051013] = {
		speaker = "我",
		prefab_name = "",
		content = "说起来，大荒这个地方，你们都知道啊？",
		id = 324051013
	},
	[324051014] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "老师跟乌说过，说魑魅就是从大荒来的。",
		id = 324051014
	},
	[324051015] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "我是觉醒以后，庚辰先生还有科尔盖找到我，问了一下我的意愿，顺便告诉过我大荒的情况。",
		id = 324051015
	},
	[324051016] = {
		speaker = "我",
