	},
	[324051017] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "可能以后再考虑吧。爷爷还需要照顾呢。",
		id = 324051017
	},
	[324051018] = {
		speaker = "我",
		prefab_name = "",
		content = "在外面有份工作可不耽误回家照顾老人。不只是因为这个吧？",
		id = 324051018
	},
	[324051019] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "哼，管理员你不懂，重明道友和乌一样，也是要成为大侠的人~去公家当差，束手束脚的多没劲。",
		id = 324051019
	},
	[324051020] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "哎呀金乌，我也没说四方院和科尔盖不好呀……",
		id = 324051020
	},
	[324051021] = {
		speaker = "我",
		prefab_name = "",
		content = "一个人确实自由一些，不过能接收到的资源也好情报也好都会比较有限。",
		id = 324051021
	},
	[324051022] = {
		speaker = "我",
		prefab_name = "",
		content = "尤其是出门在外的时候，遇到突发情况第一时间通常只能自己应付……",
		id = 324051022
	},
	[324051023] = {
		speaker = "",
		prefab_name = "",
		content = "我重重踩下刹车，叹了口气，看着前方不远处差些迎面撞上的视骸，招招手示意她们下车。",
		id = 324051023
	},
	[324051024] = {
		speaker = "我",
		prefab_name = "",
		content = "所以，该做的战斗训练，平时可别落下了。",
		id = 324051024
	},
	[324052001] = {
		speaker = "",
		prefab_name = "",
		content = "路上虽然遇到了一点阻碍，但并不多。已经习惯了没有一帆风顺的路程，以至于我把这当成了下界的常态，几乎忘了我招惹视骸的体质。",
		id = 324052001
	},
	[324052002] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "……我们算倒霉的了。要是来玉京旧城的路上这么容易遇到视骸，那工程恐怕早就泡汤了。",
		id = 324052002
	},
	[324052003] = {
		speaker = "我",
		prefab_name = "",
		content = "呃……运气不好，运气不好……",
		id = 324052003
	},
	[324052004] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "咦，不是停工了嘛？为什么前面工地上还有人？",
		id = 324052004
	},
	[324052005] = {
		speaker = "我",
		prefab_name = "",
		content = "可能通知还没传到工地上吧。",
		id = 324052005
	},
	[324052006] = {
		speaker = "",
		prefab_name = "",
		content = "坐在前排的我自然看见了金乌说的「人」，正是良工集团的施工队。随着车辆驶过废墟，来到施工区外围，施工队的工人们也发现了我们。",
		id = 324052006
	},
	[324052007] = {
		speaker = "工头",
		prefab_name = "",
		content = "呦，这不是深空之眼的小领导嘛！",
		id = 324052007
	},
	[324052008] = {
		speaker = "",
		prefab_name = "",
		content = "半个月前，我与良工集团开完会那天下午，来工地走访时见到的正是这位工头。有熟人在就省了不少事，我将车停在路边，带着金乌和重明一起下了车。",
		id = 324052008
	},
	[324052009] = {
		speaker = "",
		prefab_name = "",
		content = "工头见到从后座上跳下来的重明，原本笑眯眯的眼睛瞬间跟嘴一起睁大了，也没敢继续凑过来。",
		id = 324052009
	},
	[324052010] = {
		speaker = "工头",
		prefab_name = "",
		content = "重明小姐？您怎么也来了？",
		id = 324052010
	},
	[324052011] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "我、我和他一起的。",
		id = 324052011
	},
	[324052012] = {
		speaker = "工头",
		prefab_name = "",
		content = "啊？",
		id = 324052012
	},
	[324052013] = {
		speaker = "",
		prefab_name = "",
		content = "工头看了看重明，又看了看我，我生怕引起什么误会，连忙岔开话题。",
		id = 324052013
	},
	[324052014] = {
		speaker = "我",
		prefab_name = "",
		content = "咳……没什么，我去北边有点事，路过这里。你们接到停工通知了吗？",
		id = 324052014
	},
	[324052015] = {
		speaker = "工头",
		prefab_name = "",
		content = "接到了，说有什么地质活动风险，工地不安全……哎小领导，您不是来催我们回去的吧？",
		id = 324052015
	},
	[324052016] = {
		speaker = "我",
		prefab_name = "",
		content = "怎么，你们还不想回去？",
		id = 324052016
	},
	[324052017] = {
		speaker = "工头",
		prefab_name = "",
		content = "当然不想，凭啥回去？我们中了大标，吃了公家的预算，现在所有人都盼着我们把这些楼盖完呢，怎么能把它们扔在这里？",
		id = 324052017
	},
	[324052018] = {
		speaker = "工头",
		prefab_name = "",
		content = "重明小姐，业务部门都说您办事踏实，您给个准儿，替大伙儿说句话，这工地不能丢啊。",
		id = 324052018
	},
	[324052019] = {
