	[324052020] = {
		speaker = "我",
		prefab_name = "",
		content = "金乌。",
		id = 324052020
	},
	[324052021] = {
		speaker = "",
		prefab_name = "",
		content = "我微微摇头，打断了金乌，再看向重明。对上我的视线，重明一时有些躲闪，但似乎很快又对这种躲闪感到气馁。",
		id = 324052021
	},
	[324052022] = {
		speaker = "",
		prefab_name = "",
		content = "气馁过后便是打起精神，不再情绪用事。她抿着嘴，抬起头，看着远远近近手里还拿着工具的工人们，稍稍提高了声音。",
		id = 324052022
	},
	[324052023] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "各位师傅，你们盖起来的楼，只有你们懂得怎么保护。",
