	},
	[324052025] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "我这趟过来，就是想看看大家真实的态度，如果大家愿意服从安排，我会请大家帮忙评估一下损失。",
		id = 324052025
	},
	[324052026] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "但如果大家和我一样，不希望轩辕计划的努力就这么白费，不希望良工集团，还有每位师傅的心血白费……",
		id = 324052026
	},
	[324052027] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "就让我和大家一起努力一把，总好过回去以后再后悔。",
		id = 324052027
	},
	[324052028] = {
		speaker = "工头",
		prefab_name = "",
		content = "真的吗……那舆昊老板那边怎么交代？",
		id = 324052028
	},
	[324052029] = {
		speaker = "我",
		prefab_name = "",
		content = "舆昊老板对停工通知的反应和你们一样，但他要为集团负责，不能违抗上面的指示。",
		id = 324052029
	},
	[324052030] = {
		speaker = "我",
		prefab_name = "",
		content = "所以如果是你们自发的行为，我想他一定是会支持的，资金和资源的调度，也都有转圜的余地。",
		id = 324052030
	},
	[324052031] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "嗯，爷爷那边，我去说就好了，大家只管放心干活。",
		id = 324052031
	},
	[324052032] = {
		speaker = "工人甲",
		prefab_name = "",
		content = "你懂得多，我们听你的！",
		id = 324052032
	},
	[324052033] = {
		speaker = "",
		prefab_name = "",
		content = "有人带头，其余工人们也纷纷附和起来，工头更是带头鼓起了掌。",
		id = 324052033
	},
	[324052034] = {
		speaker = "",
		prefab_name = "",
		content = "重明像是个完成作业后交给老师的孩子，稍有些忐忑地看向我。我微笑着对她点了点头，她背在身后轻攥着的拳头才终于慢慢松开。",
		id = 324052034
	},
	[324052035] = {
