	},
	[324052042] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "以前不管是一起逛街、去昆仑玩，还是平时聊天，乌都感觉重明道友和乌差不多。可看到她这么认真的样子，又感觉乌没那么了解她了。",
		id = 324052042
