	},
	[324072040] = {
		speaker = "",
		prefab_name = "",
		content = "我与金乌落座后，必安与无咎为我们端上来两杯茶水。一揭碗，清香四溢，感觉每片花瓣都盈溢出一股肆意饱满的、无拘束的自然气息。",
		id = 324072040
	},
	[324072041] = {
