	[324081012] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "啊呀……重明道友，这么巧呀，好久不见。",
		id = 324081012
	},
	[324081013] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "怎么就「好久不见」了，不是才过去小半天吗？",
		id = 324081013
	},
	[324081014] = {
		speaker = "",
		prefab_name = "",
		content = "太阳明晃晃地挂在西边的天空，离傍晚还有些时候。金乌不说话了，憋出一头冷汗。",
		id = 324081014
	},
	[324081015] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "摔得很疼吗？要不要去找大夫看看？",
		id = 324081015
	},
	[324081016] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "不用不用，这点小伤，乌早就习惯啦。也不是哪里都有昆仑那样厚厚的雪地。",
		id = 324081016
	},
	[324081017] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "好吧……管理员小哥已经到囚云山了吗？",
		id = 324081017
	},
	[324081018] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "嗯。他要在山上修行，乌不打扰他，就下山了。你这里怎么样啦？",
		id = 324081018
	},
	[324081019] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "工地的情况我大概已经知道了……",
		id = 324081019
	},
	[324081020] = {
		speaker = "",
		prefab_name = "",
		content = "重明叹了口气，带着金乌往施工区走去。可以看到工地上并没有工人在忙碌，显然是还没有主意。",
		id = 324081020
	},
	[324081021] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "这批房子设计的抗震能力已经很高了，但一半的楼都没完工，抗震构件还不完整。",
		id = 324081021
	},
	[324081022] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "而且现在云歌石矿脉被挖空，地层本来就比较脆弱，要是受到冲击，不管是震动的强度还是塌陷的概率都会增加……",
		id = 324081022
	},
	[324081023] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "最直接有效的办法就是给工地做全方位的加固，但这和盖楼其实没什么区别，十天时间也根本不够用。",
		id = 324081023
	},
	[324081024] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "这么说的话，要是后土前辈在就好了，她会「山河搬运术」，保护工地肯定是手到擒来。",
		id = 324081024
	},
	[324081025] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "也不能总想着依赖前辈们……",
		id = 324081025
	},
	[324081026] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "诶，他们怎么往南边去了？",
		id = 324081026
	},
	[324081027] = {
		speaker = "",
		prefab_name = "",
		content = "快到施工区时，金乌忽然发现工地上闲来无事的工人们一个接一个朝南边汇去，由于建筑遮挡，金乌看不见发生了什么。重明却深吸了口气，加快了脚步。",
		id = 324081027
	},
	[324081028] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "怎么了？",
		id = 324081028
	},
	[324081029] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "我爷爷来了。",
		id = 324081029
	},
	[324081030] = {
		speaker = "工头",
		prefab_name = "",
		content = "舆昊老板，老乐……",
		id = 324081030
	},
	[324081031] = {
		speaker = "",
		prefab_name = "",
		content = "工地南边的入口停着两辆车，工头带着工人们聚过来，正看到舆昊和乐叔带着几位安保下了车，急忙迎上去。",
		id = 324081031
	},
	[324081032] = {
		speaker = "工头",
		prefab_name = "",
		content = "你们说你们来也不打声招呼。",
		id = 324081032
	},
	[324081033] = {
		speaker = "乐叔",
		prefab_name = "",
		content = "打招呼还指望你在工地上招待老板啊？",
		id = 324081033
	},
	[324081034] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "重明那丫头说她在这儿，她人呢？",
		id = 324081034
	},
	[324081035] = {
		speaker = "工头",
		prefab_name = "",
		content = "她说有个朋友路过，去北城了……您找小姐吗？我给您叫去……",
		id = 324081035
	},
	[324081036] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "哎不用不用，她在这儿就好，估摸着一会儿自己就过来了。",
		id = 324081036
	},
	[324081037] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "不是发了通知说让你们回去吗？还在这里折腾什么？",
		id = 324081037
	},
	[324081038] = {
		speaker = "工头",
		prefab_name = "",
		content = "重明小姐说要想办法保护工地，我们就一块儿想想办法，帮帮忙。",
		id = 324081038
	},
	[324081039] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "那你们想出什么办法没有？",
		id = 324081039
	},
	[324081040] = {
		speaker = "工头",
		prefab_name = "",
		content = "还……还没……",
		id = 324081040
	},
	[324081041] = {
		speaker = "",
		prefab_name = "",
		content = "舆昊闷声叹了口气，工头没话说，低着头等着挨训，可舆昊还没开口，两道身影便分开人群冒冒失失闯了进来。",
		id = 324081041
	},
	[324081042] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "爷爷！",
		id = 324081042
	},
	[324081043] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "你这丫头，就皮吧。",
		id = 324081043
	},
	[324081044] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "这回不是跟您汇报过了嘛。",
		id = 324081044
	},
	[324081045] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "这工地的事，你汇报了？先拍脑袋后张嘴。",
		id = 324081045
	},
	[324081046] = {
		speaker = "",
		prefab_name = "",
		content = "舆昊摇摇头，看向一旁的金乌，神情稍微和缓了些。",
		id = 324081046
	},
	[324081047] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "你就是金乌小友吧？感谢你照顾重明丫头了。",
		id = 324081047
	},
	[324081048] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "啊呃没有没有，老爷子您太客气了。乌和重明道……是朋友，她也帮了乌许多忙。",
		id = 324081048
	},
	[324081049] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "嗯，出门在外，能多结交一些朋友，我这个做爷爷的也放心一些。",
		id = 324081049
	},
	[324081050] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "要是她做了什么不地道的事，你记得告诉我，别人管不住这野丫头，我来管。",
		id = 324081050
	},
	[324081051] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "哎呀哪有当着我的面这么说的……",
		id = 324081051
	},
	[324081052] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "不会不会，老爷子，重明人可好了，您就放心吧。这回要留在工地上也是为了大家着想……",
		id = 324081052
	},
	[324081053] = {
		speaker = "",
		prefab_name = "",
		content = "又碰到轩辕计划的话题，金乌嘴上留了半个把门，半句话出口以后猛地反应过来，紧张兮兮地看了看身边众人的反应，好在只有舆昊稍微严肃了些。",
		id = 324081053
	},
	[324081054] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "重明啊，你的想法我都知道。现在公司内外，线上线下，质疑的、不满的、批评的……各种各样的声音都很多，我呢，也不想看到轩辕计划出问题。",
		id = 324081054
	},
	[324081055] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "有些不讲道理的家伙说得可气人了。",
		id = 324081055
	},
	[324081056] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "尖锐的声音是比想象中要多。上面不会看着良工集团平白被攻击，也在准备稳定舆情了。",
		id = 324081056
	},
	[324081057] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "可当你不止是在发声，而是要解决问题的时候，「占理」可没那么容易。",
		id = 324081057
	},
	[324081058] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "我知道的……我只是想试一试，如果没有合适的方案，我不会乱来。",
		id = 324081058
	},
	[324081059] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "这个阶段施工区的建筑，哪些非结构构件在地震中可能造成风险，分别怎么处理？",
		id = 324081059
	},
	[324081060] = {
		speaker = "",
		prefab_name = "",
		content = "突如其来的问题让重明愣了一下，她看到舆昊背着双手，知道是在考教她，也端正神情，开始回答起来。",
		id = 324081060
	},
	[324081061] = {
		speaker = "",
		prefab_name = "",
		content = "重明的回答十分利落，舆昊也不给反应，紧接着抛出下一个问题，有些口述即可，有些甚至需要重明在终端上临场作图。",
		id = 324081061
	},
	[324081062] = {
		speaker = "",
		prefab_name = "",
		content = "两人就这么一问一答，连着过了十多个问题，舆昊终于停了下来，背在身后的双手垂到身侧，点了点头。工人们纷纷鼓起掌来，朝重明报以赞许的目光。",
		id = 324081062
	},
	[324081063] = {
		speaker = "工头",
		prefab_name = "",
		content = "好！厉害啊重明小姐。",
		id = 324081063
	},
	[324081064] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "刚学过的东西，记得就清楚些。",
		id = 324081064
	},
	[324081065] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "也别骄傲。我刚才问他，你们有没有想出什么招，他说没有。",
		id = 324081065
	},
	[324081066] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "现在你在这儿，就跟爷爷说实话，十天时间，保住工地，你觉得可能吗？",
		id = 324081066
	},
	[324081067] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "办法都是想出来的嘛……",
		id = 324081067
	},
	[324081068] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "呵呵，有把事办成的心自然是好的。但凡事可而为之，不可而止之，判断和努力一样重要。",
		id = 324081068
	},
	[324081069] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "重明，你说吧。",
		id = 324081069
	},
	[324081070] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "……理论上……没可能。",
		id = 324081070
	},
	[324081071] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "诶？你这就放弃了？",
		id = 324081071
	},
	[324081072] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "但我想做的也不是让工地毫发无损。毕竟还有十天时间，只要能减少一点损失，现在的努力就是值得的。",
		id = 324081072
	},
	[324081073] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "嗯……",
		id = 324081073
	},
	[324081074] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "你有这份务实的心，爷爷就放心了。但多的资源，爷爷不会批给你，这是你的项目，控制成本也是你的责任。",
		id = 324081074
	},
	[324081075] = {
		speaker = "",
		prefab_name = "",
		content = "舆昊忽然话锋一转，连重明都没反应过来。直到舆昊招招手示意乐叔和安保们回程，她才喜出望外地晃了晃金乌的胳膊，然后跑上去给舆昊开车门。",
		id = 324081075
	},
	[324081076] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "我就知道爷爷不会生气的。",
		id = 324081076
	},
	[324081077] = {
		speaker = "舆昊",
		prefab_name = "",
		content = "唉，谁让我就你这么一个好孙女呢。\n去忙吧。",
		id = 324081077
	},
	[324081078] = {
		speaker = "",
		prefab_name = "",
		content = "目送舆昊离开，重明长长松了口气，来到工人们面前，干劲满满地举起拳头。",
		id = 324081078
	},
	[324081079] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "大家一起来想办法吧！",
		id = 324081079
	},
	[324081080] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "乌们来打弹珠吧！",
		id = 324081080
	},
	[324081081] = {
		speaker = "",
		prefab_name = "",
		content = "憋了好半天，金乌终于对蹲在一块沙堆旁的重明说出了这句话，一边从口袋里掏出一把弹珠。",
		id = 324081081
	},
	[324081082] = {
		speaker = "",
		prefab_name = "",
		content = "重明回头看着金乌，无奈地笑了笑，手里的树枝扫过沙堆，抹去她在上面写写画画的痕迹。",
		id = 324081082
	},
	[324081083] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "好难啊，金乌……",
		id = 324081083
	},
	[324081084] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "打弹珠一点都不难——哦，你说想方案。",
		id = 324081084
	},
	[324081085] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "爷爷说得对，想要解决问题是一回事，实际解决问题又是一回事。",
		id = 324081085
	},
	[324081086] = {
		speaker = "",
		prefab_name = "",
		content = "金乌抬头看着在工地各处乘凉的工人们，咬着嘴唇不知道该怎么说。",
		id = 324081086
	},
	[324081087] = {
		speaker = "",
		prefab_name = "",
		content = "两人已经在工地上待了一周，天也晴了一周，但深冬的太阳并未让她们感受到太多温暖，只觉得将工地上的热情一点点消磨了去。",
		id = 324081087
	},
	[324081088] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "这几天不是也没闲着嘛，带着师傅们做了好多事。",
		id = 324081088
	},
	[324081089] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "只是一些应急的手段，还不够……",
		id = 324081089
	},
	[324081090] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "所以，你还是想保住整个工地嘛？",
		id = 324081090
	},
	[324081091] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "……是啊，虽然在大家面前说会量力而行，可我要怎么说服自己拿着一套明显有疏漏的方案去找爷爷呢？",
		id = 324081091
	},
	[324081092] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "但越是想要完美的解决办法，花的时间就越多；花的时间越多，剩下的时间就越少；剩下的时间越少，想要完美的办法就越难……",
		id = 324081092
	},
	[324081093] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "不对不对，你这就是已经开始钻牛角尖了。老师常说，欲速则不达，休息休息，思路打开，说不定一下就悟了。",
		id = 324081093
	},
	[324081094] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "是、是吗？",
		id = 324081094
	},
	[324081095] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "当然啦，这可都是乌多年修行的感悟呀。",
		id = 324081095
	},
	[324081096] = {
		speaker = "",
		prefab_name = "",
		content = "金乌用几颗弹珠换掉重明手里的树枝，然后拿树枝在不远处的地上划起线来。",
		id = 324081096
	},
	[324081097] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "重明道友，你以前玩过弹珠吗？",
		id = 324081097
	},
	[324081098] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "没有，只看人玩过。",
		id = 324081098
	},
	[324081099] = {
