	},
	[324111031] = {
		speaker = "",
		prefab_name = "",
		content = "我接过无咎手里的玩偶。即便纯手工缝制依然非常精细，简单几道针线便将姐妹俩的神态勾画得惟妙惟肖，虽然是大头娃娃，但一眼就能看出是谁。",
		id = 324111031
	},
	[324111032] = {
