	},
	[324111038] = {
		speaker = "我",
		prefab_name = "",
		content = "我希望未来我能说出更多这样的对比，希望我能更多地了解你们。也希望你们能够好好了解自己、了解对方，多找找姐妹间的默契。",
		id = 324111038
	},
	[324111039] = {
