	},
	[324111066] = {
		speaker = "无咎",
		prefab_name = "1054ui_story",
		content = "就算你们不在，也会发生这样的事吧……万一打不过，就逃跑再去搬救兵。",
		id = 324111066
	},
	[324111067] = {
		speaker = "我",
