	},
	[324121021] = {
		speaker = "我",
		prefab_name = "",
		content = "尽力而为吧。\n哦，对了，这个剑匣——",
		id = 324121021
	},
	[324121022] = {
		speaker = "",
		prefab_name = "",
		content = "我取下身后的剑匣，放在地上，一来长时间背着确实疲累，二来我还没忘了这是谁的东西。",
		id = 324121022
	},
	[324121023] = {
		speaker = "我",
		prefab_name = "",
		content = "在大荒兜了一圈，可惜没找到你说的能让承钧显现的人。我是放回原处，还是——",
		id = 324121023
	},
	[324121024] = {
		speaker = "长琴",
		prefab_name = "",
		content = "若对你有用，你就带着吧，总好过在我这里平白放着。",
		id = 324121024
	},
	[324121025] = {
		speaker = "我",
		prefab_name = "",
		content = "行……确实有用，望舒和孟章都说对神剑有助益。",
		id = 324121025
	},
	[324121026] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "管理员，半个小时啊……乌要陪你一起等吗？",
		id = 324121026
	},
	[324121027] = {
		speaker = "我",
		prefab_name = "",
		content = "这……",
		id = 324121027
	},
	[324121028] = {
		speaker = "",
		prefab_name = "",
		content = "我有些不确定起来，让金乌留在这里确实有些浪费人力，可又难保我不会遇上什么问题。",
		id = 324121028
	},
	[324121029] = {
		speaker = "",
		prefab_name = "",
		content = "正纠结的时候，我的终端忽然响了起来，低头一看，是孟章发来的消息。长琴顺势把话头接了过去。",
		id = 324121029
	},
	[324121030] = {
		speaker = "长琴",
		prefab_name = "",
		content = "你便是羲和前辈的弟子，金乌吧？",
		id = 324121030
	},
	[324121031] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "咦，您认得乌？",
		id = 324121031
	},
	[324121032] = {
		speaker = "长琴",
		prefab_name = "",
		content = "羲和前辈常说起你。你的神能……有用过长阳的痕迹，前辈已经将长阳交给你了吗？",
		id = 324121032
	},
	[324121033] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "没有，那把剑还在若木宫里挂着呢。不过乌用过一次，确实好使。",
		id = 324121033
	},
	[324121034] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "您连这个都能看出来？",
		id = 324121034
	},
	[324121035] = {
		speaker = "长琴",
		prefab_name = "",
		content = "毕竟是我铸的剑，在谁手里用过，多少会有感应……你用那剑做什么了？",
		id = 324121035
	},
	[324121036] = {
		speaker = "",
		prefab_name = "",
		content = "说到这个，金乌一下来了兴致，绘声绘色地将自己在旸山镇压混沌的经历说了一遍。",
		id = 324121036
	},
	[324121037] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "……总之就这样，混沌被乌打跑啦。但这回下山的时候，它还敢向乌逞凶，实在太嚣张。",
		id = 324121037
	},
	[324121038] = {
		speaker = "长琴",
		prefab_name = "",
		content = "没有一鼓作气消灭它么？",
		id = 324121038
	},
	[324121039] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "啊？您可别难为乌，老师都做不到的事，乌哪有办法？能把它封印起来就谢天谢地啦。",
		id = 324121039
	},
	[324121040] = {
		speaker = "长琴",
		prefab_name = "",
		content = "羲和前辈也是这么说的？",
		id = 324121040
	},
	[324121041] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "那、那倒没有，乌这么猜的。",
		id = 324121041
	},
	[324121042] = {
		speaker = "",
		prefab_name = "",
		content = "金乌挠挠头，讲故事的劲头稍微消下去一些，这才想起一直没吭声的我，转过头来看了我一眼，却又睁大了眼睛。",
		id = 324121042
	},
	[324121043] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "哎，你身后！",
		id = 324121043
	},
	[324121044] = {
		speaker = "",
		prefab_name = "",
		content = "盯着终端的我这才回过神，转过身，看见那道无比熟悉、流光溢彩却又混沌一片的空间裂缝，终于松了口气。",
		id = 324121044
	},
	[324121045] = {
		speaker = "",
		prefab_name = "",
		content = "可放松过后，我下意识地看了眼时间，却又紧张起来。",
		id = 324121045
	},
	[324121046] = {
		speaker = "望舒",
		prefab_name = "10170ui_story",
		content = "十天以后，还是这个时间，我再开一条通道，入口还在长琴那里。",
		id = 324121046
	},
	[324121047] = {
		speaker = "我",
		prefab_name = "",
		content = "好吧，总之我早点过去等你，只要你打开通道，我马上过来……",
		id = 324121047
	},
	[324121048] = {
		speaker = "我",
		prefab_name = "",
		content = "提前了……",
		id = 324121048
	},
	[324121049] = {
		speaker = "长琴",
		prefab_name = "",
		content = "怎么？",
		id = 324121049
	},
	[324121050] = {
		speaker = "我",
		prefab_name = "",
		content = "如果是别人，这十多分钟的误差可能不算什么，但她是望舒……她说了「还是这个时间」，如果可以，她是会看着表等到一分一秒都不差的。",
		id = 324121050
	},
	[324121051] = {
		speaker = "我",
		prefab_name = "",
		content = "提前打开通道，就说明她没法等到准点了……我得赶紧过去。",
		id = 324121051
	},
	[324121052] = {
		speaker = "",
		prefab_name = "",
		content = "我背上剑匣，看到金乌好奇地往通道里张望，连忙拦住她。",
		id = 324121052
	},
	[324121053] = {
		speaker = "我",
		prefab_name = "",
		content = "你可千万别碰，你老师都碰不得。",
		id = 324121053
	},
	[324121054] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "哦……你现在要走了吗？那乌回囚云山了。",
		id = 324121054
	},
	[324121055] = {
		speaker = "我",
		prefab_name = "",
		content = "孟章正在组织人手，准备出发去囚云山，等两地对接以后直接去大荒支援，你倒不用着急……",
		id = 324121055
	},
	[324121056] = {
		speaker = "我",
		prefab_name = "",
		content = "不过他说旸山又出事了，好像混沌又开始冲击结界，弄得羲和现在也脱不了身。你要不回旸山看看？",
		id = 324121056
	},
	[324121057] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "有老师在应该没事吧……不过好像有些太巧了？穷奇开始闹，它也开始闹。",
		id = 324121057
	},
	[324121058] = {
		speaker = "我",
		prefab_name = "",
		content = "这也是你们要多留意的地方，我总觉得这事不单纯。要怎么做，该由你自己判断了。",
		id = 324121058
	},
	[324121059] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "乌……乌不知道，管理员，你觉得呢？",
		id = 324121059
	},
	[324121060] = {
		speaker = "",
		prefab_name = "",
		content = "我无奈地拍了拍她的肩膀，见她还是有些局促，只好捏了捏她的脸。",
		id = 324121060
	},
	[324121061] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "哎呦管理员——",
		id = 324121061
	},
	[324121062] = {
		speaker = "我",
		prefab_name = "",
		content = "别钻牛角尖，清醒一点。我遇到过不知道多少两难的情况，没人告诉过我应该怎么选。这种时候就想想自己眼下能做什么，然后去做就是了。",
		id = 324121062
	},
	[324121063] = {
		speaker = "我",
		prefab_name = "",
		content = "你也别太小瞧自己。你有颗大心脏，这非常难得。不管是帮你老师镇压混沌，还是头回御剑这么远带我来昆仑，都是初次尝试就成功了。",
		id = 324121063
	},
	[324121064] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "那……「大侠」就是不能在重要的事上掉链子的。",
		id = 324121064
	},
	[324121065] = {
		speaker = "我",
		prefab_name = "",
		content = "一个人一直用故事里完美的「大侠」来要求自己，这不就是一件很了不起的事吗？",
		id = 324121065
	},
	[324121066] = {
		speaker = "",
		prefab_name = "",
		content = "空间裂缝开始出现轻微的不稳定的迹象，没时间再让我多做劝导。我最后揉了揉金乌的脑袋，朝长琴点头致意，转身匆忙走进了裂缝。",
		id = 324121066
	},
	[324121067] = {
		speaker = "",
		prefab_name = "",
		content = "我走后，冰窟中的空间裂缝很快消失，金乌愣愣地站在原地看着，好像那些流转的光彩会给她答案似的。",
		id = 324121067
	},
	[324121068] = {
		speaker = "长琴",
		prefab_name = "",
		content = "还不出发吗？",
		id = 324121068
	},
	[324121069] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "可是没有人找乌帮忙，乌自己过去，会不会又帮倒忙？乌已经帮了好多次倒忙了……",
		id = 324121069
	},
	[324121070] = {
		speaker = "长琴",
		prefab_name = "",
		content = "无论是谁，遇到困难的时候，都会希望得到帮助。既然你不是有意捣乱，我想没有人会责怪你，也都是需要你的。",
		id = 324121070
	},
	[324121071] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "是这样吗……",
		id = 324121071
	},
	[324121072] = {
		speaker = "长琴",
		prefab_name = "",
		content = "当然。人人都有少不更事的时候，只要善良的心没有变，最后总会变得成熟可靠。",
		id = 324121072
	},
	[324121073] = {
		speaker = "长琴",
		prefab_name = "",
		content = "我认识一个朋友，年轻的时候从来居无定所，一只葫芦一把剑，从虚恒南边走到北边，遇上什么稀奇的事都喜欢掺和一下。",
		id = 324121073
	},
	[324121074] = {
		speaker = "长琴",
		prefab_name = "",
		content = "有一次她路过一个村子，听两个孩子说附近的水塘里有妖怪，提着剑就去除妖。",
		id = 324121074
	},
	[324121075] = {
		speaker = "长琴",
		prefab_name = "",
		content = "那两个孩子带她到了水塘边，果然看到池底有个奇形怪状的东西，不似鱼类，还发出嗡嗡的怪声。孩子被吓跑了，她也没多想，一剑就刺了下去。",
		id = 324121075
	},
	[324121076] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "结果没刺着，把妖怪放跑了吗？",
		id = 324121076
	},
	[324121077] = {
		speaker = "长琴",
		prefab_name = "",
		content = "她出手倒不至于空了……只是把那东西拎上来一看，是台机器。",
		id = 324121077
	},
	[324121078] = {
		speaker = "长琴",
		prefab_name = "",
		content = "没过多久来了一车人，看到那机器被刺得不成样了，痛心疾首。原来是水文站的，从诺伊汉萨进了这台设备，就这么报废了。",
		id = 324121078
	},
	[324121079] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "噫……这下闯大祸了。不过换成乌的话，可能也中招了……",
		id = 324121079
	},
	[324121080] = {
		speaker = "长琴",
		prefab_name = "",
		content = "呵呵，要不怎么说，什么样的师父带出什么样的徒弟呢？",
		id = 324121080
	},
	[324121081] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "……啊？你说的这个朋友，是老师吗？",
		id = 324121081
	},
	[324121082] = {
		speaker = "长琴",
		prefab_name = "",
		content = "不相信么？",
		id = 324121082
	},
	[324121083] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "不对不对，老师什么时候「一只葫芦一把剑」了……",
		id = 324121083
	},
	[324121084] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "哦，乌想起来了，你说的是常曦师叔吧，她的确是这个扮相。",
		id = 324121084
	},
	[324121085] = {
		speaker = "长琴",
		prefab_name = "",
		content = "你说的常曦师叔，是不是前几日在昭黎山救了你与那位管理员的人？",
		id = 324121085
	},
	[324121086] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "咦，这您也知道啊！",
		id = 324121086
	},
	[324121087] = {
		speaker = "长琴",
		prefab_name = "",
		content = "你这小丫头……真亏你到现在还没发现，那就是你老师，羲和前辈。",
		id = 324121087
	},
	[324121088] = {
		speaker = "",
		prefab_name = "",
		content = "金乌愣住了，「常曦师叔」和「羲和老师」两个形象在脑海中来回打转，一时想不出从哪里开始问。",
		id = 324121088
	},
	[324121089] = {
		speaker = "长琴",
		prefab_name = "",
		content = "她知道你总怕自己让她操心，若是直接出面救你，难免影响你的积极性，所以才以天通术改换了样貌。",
		id = 324121089
	},
	[324121090] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "那真正的常曦师叔呢？老师明明说有这样一个人……",
		id = 324121090
	},
	[324121091] = {
		speaker = "长琴",
		prefab_name = "",
		content = "那位……若还有机会，未来也许能见到吧。",
		id = 324121091
	},
	[324121092] = {
		speaker = "",
		prefab_name = "",
		content = "长琴像是想起了什么，微微叹了口气。金乌看上去有些失落，又苦恼地嘟起嘴，原地蹲了下来。",
		id = 324121092
	},
	[324121093] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "所以老师住在若木宫，不是因为喜欢隐居，只是因为要镇压混沌。",
		id = 324121093
	},
	[324121094] = {
		speaker = "长琴",
		prefab_name = "",
		content = "正是如此。只要混沌被消灭，想来第二天她就该云游去了。",
		id = 324121094
	},
	[324121095] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "那不是变成死局了？乌也想消灭混沌，可又没有办法……",
		id = 324121095
	},
	[324121096] = {
		speaker = "长琴",
		prefab_name = "",
		content = "办法你已见过了。",
		id = 324121096
	},
	[324121097] = {
		speaker = "金乌",
		prefab_name = "1070ui_story",
		content = "啊？",
		id = 324121097
	},
	[324121098] = {
		speaker = "长琴",
		prefab_name = "",
		content = "……你既然用过长阳，那我便斗胆替羲和前辈告诉你实情吧。",
		id = 324121098
	},
	[324121099] = {
		speaker = "长琴",
		prefab_name = "",
		content = "长阳之火至纯至烈，催动到极致，不再囿于有形之火，即便是无形之物，亦可熔毁炼化。",
		id = 324121099
	},
	[324121100] = {
		speaker = "长琴",
		prefab_name = "",
		content = "当年为应对大荒的祸事，羲和前辈领走了长阳剑，但她并非合适的剑主，也发挥不了长阳的全部威能。",
		id = 324121100
	},
	[324121101] = {
		speaker = "长琴",
		prefab_name = "",
		content = "镇压混沌后，她知道这把剑终归需要一位合适的剑主，于是一直在寻找。",
		id = 324121101
	},
	[324121102] = {
