	},
	[324151103] = {
		speaker = "",
		prefab_name = "",
		content = "在天禄贸易众人的协助下，重明终于等到了地震平息的一刻，饶是如此，她依然累得几乎虚脱过去。",
		id = 324151103
	},
	[324151104] = {
		speaker = "",
		prefab_name = "",
		content = "广播里开始播报大荒封锁成功解除的消息，可以想象此时的虚恒线上线下有多热闹，可重明只是靠坐在石墩上，一副心有余悸的样子。",
		id = 324151104
	},
	[324151105] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "……没想到……这么久……",
		id = 324151105
	},
	[324151106] = {
		speaker = "陆吾",
		prefab_name = "1060ui_story",
		content = "能坚持这么久，很了不起啊，哈哈。",
		id = 324151106
	},
	[324151107] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "你们是怎么知道……",
		id = 324151107
	},
	[324151108] = {
		speaker = "英招",
		prefab_name = "1074ui_story",
		content = "我妹妹麟钰是天理阁的学生，执明代理把你的计划告诉了她，她又告诉了我，说你可能需要帮忙。",
		id = 324151108
	},
	[324151109] = {
		speaker = "英招",
		prefab_name = "1074ui_story",
		content = "我就跟小老板提了一嘴，小老板就带我们来了。",
