	},
	[324151110] = {
		speaker = "禄良",
		prefab_name = "1072ui_story",
		content = "良工集团和天禄贸易都是老字号，互帮互助应该的嘛~",
		id = 324151110
	},
	[324151111] = {
		speaker = "",
		prefab_name = "",
		content = "似乎是并不希望引人注目，地震结束后，天禄贸易来的大部分人都立刻离开了，只有禄良带着少数几人来确认重明的状况。见她没事，大家都松了口气。",
		id = 324151111
	},
	[324151112] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "……要不是你们帮忙，我今天可能都回不去了。",
		id = 324151112
	},
	[324151113] = {
		speaker = "陆吾",
		prefab_name = "1060ui_story",
		content = "怎么还说这个？要不是你和这把神剑，今天这人类重建的第一座城市可就完蛋了。",
		id = 324151113
	},
	[324151114] = {
		speaker = "重明",
		prefab_name = "10171ui_story",
		content = "一码归一码……总之我欠各位一个天大的人情，不管天禄贸易需要什么帮助，我一定——",
		id = 324151114
	},
	[324151115] = {
