		content = "哎呀，行啦行啦~说咱们都是老字号，可没让你真把咱当生意人。",
		id = 324151115
	},
	[324151116] = {
		speaker = "禄良",
		prefab_name = "1072ui_story",
		content = "不过你要是想报答的话，考不考虑加入天禄贸易呀？",
		id = 324151116
	},
	[324151117] = {
		speaker = "重明",
