	},
	[324151118] = {
		speaker = "禄良",
		prefab_name = "1072ui_story",
		content = "你不能让舆昊老板知道你是修正者，又有心用这份力量为大家做点事儿，那天禄贸易可太适合你了。",
		id = 324151118
	},
	[324151119] = {
