	},
	[324151120] = {
		speaker = "英招",
		prefab_name = "1074ui_story",
		content = "小老板……你忘了舆昊老板想让她接班的，你这样挖墙角，不怕舆昊老板跟咱们吹胡子？",
		id = 324151120
	},
	[324151121] = {
		speaker = "禄良",
		prefab_name = "1072ui_story",
		content = "哦，这倒也是。那你给人家找个路子？",
		id = 324151121
	},
	[324151122] = {
		speaker = "英招",
		prefab_name = "1074ui_story",
		content = "要我说，天理阁就不错。麟钰在那儿学得很好……",
